# Let me now understand the approach better and begin implementing
# The grex algorithm:
# 1. Input: list of strings
# 2. For each string, preprocess characters based on flags
# 3. Build a trie from the preprocessed strings
# 4. Build a DFA from the trie
# 5. Minimize the DFA
# 6. Generate regex from the minimized DFA

# Key: The character preprocessing happens BEFORE DFA construction
# When -d flag is set, digits become a single "digit" token
# When -w flag is set, word chars become a single "word" token, etc.

# Let me write a Rust implementation from scratch
# I'll implement the full algorithm

mkdir -p grex_impl/src

cat > grex_impl/src/main.rs << 'MAINEOF'
mod cli;
mod grapheme;
mod dfa;
mod regex;

use std::fs;
use std::io::{self, BufRead};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let config = cli::parse_args(&args);

    match config {
        Ok(cfg) => {
            let test_cases = match get_test_cases(&cfg) {
                Ok(cases) => cases,
                Err(e) => {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            };

            if test_cases.is_empty() {
                eprintln!("error: no test cases provided");
                std::process::exit(1);
            }

            let regexp = regex::build_regexp(&test_cases, &cfg);
            println!("{}", regexp);
        }
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(2);
        }
    }
}

fn get_test_cases(cfg: &cli::Config) -> Result<Vec<String>, String> {
    if let Some(ref file_path) = cfg.file {
        if file_path == "-" {
            return Err("the specified file could not be found".to_string());
        }
        let content = fs::read_to_string(file_path)
            .map_err(|_| "the specified file could not be found".to_string())?;
        let lines: Vec<String> = content
            .lines()
            .map(|l| l.to_string())
            .collect();
        Ok(lines)
    } else {
        Ok(cfg.input.clone())
    }
}
