use std::process;

#[derive(Debug, Clone)]
pub struct Config {
    pub input: Vec<String>,
    pub file: Option<String>,
    pub digits: bool,
    pub non_digits: bool,
    pub spaces: bool,
    pub non_spaces: bool,
    pub words: bool,
    pub non_words: bool,
    pub escape: bool,
    pub with_surrogates: bool,
    pub repetitions: bool,
    pub min_repetitions: usize,
    pub min_substring_length: usize,
    pub no_start_anchor: bool,
    pub no_end_anchor: bool,
    pub no_anchors: bool,
    pub verbose: bool,
    pub colorize: bool,
    pub ignore_case: bool,
    pub capture_groups: bool,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            input: Vec::new(),
            file: None,
            digits: false,
            non_digits: false,
            spaces: false,
            non_spaces: false,
            words: false,
            non_words: false,
            escape: false,
            with_surrogates: false,
            repetitions: false,
            min_repetitions: 1,
            min_substring_length: 1,
            no_start_anchor: false,
            no_end_anchor: false,
            no_anchors: false,
            verbose: false,
            colorize: false,
            ignore_case: false,
            capture_groups: false,
        }
    }
}

const VERSION: &str = "grex 1.4.6";
const AUTHOR: &str = "© 2019-today Peter M. Stahl <pemistahl@gmail.com>";

pub fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1;
    let mut input_args: Vec<String> = Vec::new();
    let mut has_file = false;
    let mut reading_stdin_file = false;

    // Check for help and version first
    for arg in &args[1..] {
        if arg == "-h" || arg == "--help" {
            print_help();
            process::exit(0);
        }
        if arg == "-v" || arg == "--version" {
            println!("{}", VERSION);
            process::exit(0);
        }
    }

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-f" | "--file" => {
                has_file = true;
                i += 1;
                if i < args.len() {
                    config.file = Some(args[i].clone());
                    if args[i] == "-" {
                        reading_stdin_file = true;
                    }
                } else {
                    return Err(format!("error: argument '{}' requires a value but none was supplied\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n", arg));
                }
            }
            "--min-repetitions" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<usize>() {
                        Ok(n) => config.min_repetitions = n,
                        Err(_) => {
                            return Err(format!("error: invalid value '{}' for '--min-repetitions <QUANTITY>': invalid digit found in string\n\nFor more information, try '--help'.\n", args[i]));
                        }
                    }
                }
            }
            "--min-substring-length" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<usize>() {
                        Ok(n) => config.min_substring_length = n,
                        Err(_) => {
                            return Err(format!("error: invalid value '{}' for '--min-substring-length <LENGTH>': invalid digit found in string\n\nFor more information, try '--help'.\n", args[i]));
                        }
                    }
                }
            }
            "--with-surrogates" => config.with_surrogates = true,
            "--no-start-anchor" => config.no_start_anchor = true,
            "--no-end-anchor" => config.no_end_anchor = true,
            "--no-anchors" => config.no_anchors = true,
            _ if arg.starts_with('-') && !arg.starts_with("--") => {
                // Handle combined short flags like -dgr
                for ch in arg[1..].chars() {
                    match ch {
                        'd' => config.digits = true,
                        'D' => config.non_digits = true,
                        's' => config.spaces = true,
                        'S' => config.non_spaces = true,
                        'w' => config.words = true,
                        'W' => config.non_words = true,
                        'e' => config.escape = true,
                        'r' => config.repetitions = true,
                        'x' => config.verbose = true,
                        'c' => config.colorize = true,
                        'i' => config.ignore_case = true,
                        'g' => config.capture_groups = true,
                        'h' => {
                            print_help();
                            process::exit(0);
                        }
                        'v' => {
                            println!("{}", VERSION);
                            process::exit(0);
                        }
                        _ => {
                            return Err(format!("error: unexpected argument '-{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n", ch));
                        }
                    }
                }
            }
            _ => {
                input_args.push(arg.clone());
            }
        }
        i += 1;
    }

    // If file is "-", read filename from stdin - but this is not normal stdin reading
    // If input is "-", read test cases from stdin
    if !has_file && input_args.len() == 1 && input_args[0] == "-" {
        // Read from stdin
        let stdin = std::io::stdin();
        let mut cases = Vec::new();
        for line in stdin.lock().lines() {
            match line {
                Ok(l) => cases.push(l),
                Err(_) => break,
            }
        }
        config.input = cases;
    } else if !has_file {
        config.input = input_args;
    }

    // Validate: must have either input or file
    if !has_file && config.input.is_empty() {
        return Err(format!(
            "error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n"
        ));
    }

    Ok(config)
}

fn print_help() {
    println!("{}", VERSION);
    println!("{}", AUTHOR);
    println!("Licensed under the Apache License, Version 2.0");
    println!("Downloadable from https://crates.io/crates/grex");
    println!("Source code at https://github.com/pemistahl/grex");
    println!();
    println!("grex generates regular expressions from user-provided test cases.");
    println!();
    println!("Usage: grex [OPTIONS] {{INPUT...|--file <FILE>}}");
    println!();
    println!("Input:");
    println!("  [INPUT]...");
    println!("          One or more test cases separated by blank space");
    println!("          ");
    println!("          Use a hyphen `-` to read test cases from standard input.");
    println!("          ");
    println!("          Conflicts with --file.");
    println!();
    println!("  -f, --file <FILE>");
    println!("          Reads test cases on separate lines from a file.");
    println!("          ");
    println!("          Lines may be ended with either a newline `\\n` or a carriage return with a line feed");
    println!("          `\\r\\n`. The final line ending is optional.");
    println!("          ");
    println!("          Use a hyphen `-` to read the filename from standard input.");
    println!("          ");
    println!("          Conflicts with INPUT...");
    println!();
    println!("Digit Options:");
    println!("  -d, --digits");
    println!("          Converts any Unicode decimal digit to \\d.");
    println!("          ");
    println!("          Takes precedence over --words if both are set. Decimal digits are converted to \\d,");
    println!("          remaining word characters to \\w.");
    println!("          ");
    println!("          Takes precedence over --non-spaces if both are set. Decimal digits are converted to \\d,");
    println!("          remaining non-space characters to \\S.");
    println!();
    println!("  -D, --non-digits");
    println!("          Converts any character which is not a Unicode decimal digit to \\D.");
    println!("          ");
    println!("          Takes precedence over --non-words if both are set. Non-digits which are also non-word");
    println!("          characters are converted to \\D.");
    println!("          ");
    println!("          Takes precedence over --non-spaces if both are set. Non-digits which are also non-space");
    println!("          characters are converted to \\D.");
    println!();
    println!("Whitespace Options:");
    println!("  -s, --spaces");
    println!("          Converts any Unicode whitespace character to \\s.");
    println!("          ");
    println!("          Takes precedence over --non-digits if both are set. Whitespace is converted to \\s,");
    println!("          remaining non-digits to \\D.");
    println!("          ");
    println!("          Takes precedence over --non-words if both are set. Whitespace is converted to \\s,");
    println!("          remaining non-word characters to \\W.");
    println!();
    println!("  -S, --non-spaces");
    println!("          Converts any character which is not a Unicode whitespace character to \\S");
    println!();
    println!("Word Options:");
    println!("  -w, --words");
    println!("          Converts any Unicode word character to \\w.");
    println!("          ");
    println!("          Takes precedence over --non-digits if both are set. Word characters are converted to \\w,");
    println!("          remaining non-digits to \\D.");
    println!("          ");
    println!("          Takes precedence over --non-spaces if both are set. Word characters are converted to \\w,");
    println!("          remaining non-whitespace to \\S.");
    println!();
    println!("  -W, --non-words");
    println!("          Converts any character which is not a Unicode word character to \\W.");
    println!("          ");
    println!("          Takes precedence over --non-spaces if both are set. Non-word characters which are also");
    println!("          non-whitespace are converted to \\W.");
    println!();
    println!("Escaping Options:");
    println!("  -e, --escape");
    println!("          Replaces all non-ASCII characters with unicode escape sequences");
    println!();
    println!("      --with-surrogates");
    println!("          Converts astral code points to surrogate pairs if --escape is set");
    println!();
    println!("Repetition Options:");
    println!("  -r, --repetitions");
    println!("          Detects repeated non-overlapping substrings and converts them to {{min,max}} quantifier");
    println!("          notation");
    println!();
    println!("      --min-repetitions <QUANTITY>");
    println!("          Specifies the minimum quantity of substring repetitions to be converted if --repetitions");
    println!("          is set");
    println!("          ");
    println!("          [default: 1]");
    println!();
    println!("      --min-substring-length <LENGTH>");
    println!("          Specifies the minimum length a repeated substring must have in order to be converted if");
    println!("          --repetitions is set");
    println!("          ");
    println!("          [default: 1]");
    println!();
    println!("Anchor Options:");
    println!("      --no-start-anchor");
    println!("          Removes the caret anchor `^` from the resulting regular expression.");
    println!("          ");
    println!("          By default, the caret anchor is added to every generated regular expression which");
    println!("          guarantees that the expression matches the test cases given as input only at the start of");
    println!("          a string.");
    println!("          ");
    println!("          This flag removes the anchor, thereby allowing to match the test cases also when they do");
    println!("          not occur at the start of a string.");
    println!();
    println!("      --no-end-anchor");
    println!("          Removes the dollar sign anchor `$` from the resulting regular expression.");
    println!("          ");
    println!("          By default, the dollar sign anchor is added to every generated regular expression which");
    println!("          guarantees that the expression matches the test cases given as input only at the end of a");
    println!("          string.");
    println!("          ");
    println!("          This flag removes the anchor, thereby allowing to match the test cases also when they do");
    println!("          not occur at the end of a string.");
    println!();
    println!("      --no-anchors");
    println!("          Removes the caret and dollar sign anchors from the resulting regular expression.");
    println!("          ");
    println!("          By default, anchors are added to every generated regular expression which guarantees that");
    println!("          the expression exactly matches only the test cases given as input and nothing else.");
    println!("          ");
    println!("          This flag removes the anchors, thereby allowing to match the test cases also when they");
    println!("          occur within a larger string that contains other content as well.");
    println!();
    println!("Display Options:");
    println!("  -x, --verbose");
    println!("          Produces a nicer-looking regular expression in verbose mode");
    println!();
    println!("  -c, --colorize");
    println!("          Provides syntax highlighting for the resulting regular expression");
    println!();
    println!("Miscellaneous Options:");
    println!("  -i, --ignore-case");
    println!("          Performs case-insensitive matching, letters match both upper and lower case");
    println!();
    println!("  -g, --capture-groups");
    println!("          Replaces non-capturing groups with capturing ones");
    println!();
    println!("  -h, --help");
    println!("          Prints help information");
    println!();
    println!("  -v, --version");
    println!("          Prints version information");
}
