            "--min-substring-length" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<usize>() {
                        Ok(n) => config.min_substring_length = n,
                        Err(_) => {
                            return Err(format!("error: invalid value '{}' for '--min-substring-length <LENGTH>': invalid digit found in string\n\nFor more information, try '--help'.\n", args[i]));
                        }
                    }
                }
            }
            "--with-surrogates" => config.with_surrogates = true,
            "--no-start-anchor" => config.no_start_anchor = true,
            "--no-end-anchor" => config.no_end_anchor = true,
            "--no-anchors" => config.no_anchors = true,
            _ if arg.starts_with('-') && !arg.starts_with("--") => {
                // Handle combined short flags like -dgr
                for ch in arg[1..].chars() {
                    match ch {
                        'd' => config.digits = true,
                        'D' => config.non_digits = true,
                        's' => config.spaces = true,
                        'S' => config.non_spaces = true,
                        'w' => config.words = true,
                        'W' => config.non_words = true,
                        'e' => config.escape = true,
                        'r' => config.repetitions = true,
                        'x' => config.verbose = true,
                        'c' => config.colorize = true,
                        'i' => config.ignore_case = true,
                        'g' => config.capture_groups = true,
                        'h' => {
                            print_help();
                            process::exit(0);
                        }
                        'v' => {
                            println!("{}", VERSION);
                            process::exit(0);
                        }
                        _ => {
                            return Err(format!("error: unexpected argument '-{}' found\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n", ch));
                        }
                    }
                }
            }
            _ => {
                input_args.push(arg.clone());
            }
        }
        i += 1;
    }

    // If file is "-", read filename from stdin - but this is not normal stdin reading
    // If input is "-", read test cases from stdin
    if !has_file && input_args.len() == 1 && input_args[0] == "-" {
        // Read from stdin
        let stdin = std::io::stdin();
        let mut cases = Vec::new();
        for line in stdin.lock().lines() {
            match line {
                Ok(l) => cases.push(l),
                Err(_) => break,
            }
        }
        config.input = cases;
    } else if !has_file {
        config.input = input_args;
    }

    // Validate: must have either input or file
    if !has_file && config.input.is_empty() {
        return Err(format!(
            "error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n"
        ));
    }

    Ok(config)
}

