/// Check if char is a Unicode decimal digit
pub fn is_digit(c: char) -> bool {
    c.is_numeric() && c.is_ascii_digit() == false || c.is_ascii_digit()
}

/// More precise: is Unicode decimal digit (Nd category)
pub fn is_unicode_digit(c: char) -> bool {
    // Unicode decimal digits include ASCII 0-9 plus digits from other scripts
    c.is_numeric() // This is close but not exact
}

/// Check if char is a Unicode word character (\w equivalent: [a-zA-Z0-9_] + Unicode letters/digits)
pub fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// Check if char is whitespace
pub fn is_whitespace(c: char) -> bool {
    c.is_whitespace()
}

/// Escape a character for use in regex
pub fn escape_char(c: char) -> String {
    match c {
        '.' | '+' | '*' | '?' | '^' | '$' | '{' | '}' | '[' | ']' | '(' | ')' | '|' | '\\' => {
            format!("\\{}", c)
        }
        c if c.is_ascii() => c.to_string(),
        c => c.to_string(),
    }
}

/// Escape a character for use inside a character class
pub fn escape_char_in_class(c: char) -> String {
    match c {
        ']' | '\\' | '^' | '-' => format!("\\{}", c),
        c => c.to_string(),
    }
}
