/// A DFA state
#[derive(Debug, Clone)]
pub struct State {
    pub transitions: BTreeMap<Token, usize>,
    pub is_accepting: bool,
}

impl State {
    pub fn new(is_accepting: bool) -> Self {
        State {
            transitions: BTreeMap::new(),
            is_accepting,
        }
    }
}

/// A Deterministic Finite Automaton
pub struct DFA {
    pub states: Vec<State>,
    pub initial: usize,
}

impl DFA {
    pub fn new() -> Self {
        DFA {
            states: vec![State::new(false)],
            initial: 0,
        }
    }

    pub fn add_state(&mut self, is_accepting: bool) -> usize {
        let id = self.states.len();
        self.states.push(State::new(is_accepting));
        id
    }

    pub fn add_transition(&mut self, from: usize, token: Token, to: usize) {
        self.states[from].transitions.insert(token, to);
    }

    pub fn set_accepting(&mut self, state: usize) {
        self.states[state].is_accepting = true;
    }

    /// Build DFA from a list of token sequences
    pub fn from_token_sequences(sequences: &[Vec<Token>]) -> Self {
        let mut dfa = DFA::new();

        for seq in sequences {
            let mut current = dfa.initial;
            for token in seq {
                let next = if let Some(&next) = dfa.states[current].transitions.get(token) {
                    next
                } else {
                    let new_state = dfa.add_state(false);
                    dfa.states[current].transitions.insert(token.clone(), new_state);
                    new_state
                };
                current = next;
            }
            dfa.set_accepting(current);
        }

        dfa
    }

    /// Minimize the DFA using Hopcroft's algorithm
    pub fn minimize(&self) -> Self {
        let n = self.states.len();
        if n == 0 {
            return DFA::new();
        }

        // Partition states into accepting and non-accepting
        let accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| self.states[s].is_accepting)
            .collect();
        let non_accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| !self.states[s].is_accepting)
            .collect();

        let mut partition: Vec<BTreeSet<usize>> = Vec::new();
        if !accepting.is_empty() {
            partition.push(accepting);
        }
        if !non_accepting.is_empty() {
            partition.push(non_accepting);
        }
        if partition.is_empty() {
            partition.push(BTreeSet::new());
        }

        // Collect all tokens in the DFA
