use std::collections::{HashMap, BTreeMap, BTreeSet, VecDeque};

/// A token representing a character or character class
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Token {
    Literal(char),
    MultiChar(String), // For multi-codepoint grapheme clusters
    Digit,             // \d
    NonDigit,          // \D
    Space,             // \s
    NonSpace,          // \S
    Word,              // \w
    NonWord,           // \W
}

impl Token {
    pub fn to_regex_str(&self, escape: bool, with_surrogates: bool) -> String {
        match self {
            Token::Literal(c) => {
                if escape && *c as u32 > 127 {
                    char_to_escape(*c, with_surrogates)
                } else {
                    escape_regex_char(*c)
                }
            }
            Token::MultiChar(s) => {
                if escape {
                    s.chars()
                        .map(|c| if c as u32 > 127 { char_to_escape(c, with_surrogates) } else { escape_regex_char(c) })
                        .collect()
                } else {
                    s.chars().map(|c| escape_regex_char(c)).collect()
                }
            }
            Token::Digit => "\\d".to_string(),
            Token::NonDigit => "\\D".to_string(),
            Token::Space => "\\s".to_string(),
            Token::NonSpace => "\\S".to_string(),
            Token::Word => "\\w".to_string(),
            Token::NonWord => "\\W".to_string(),
        }
    }

    pub fn to_char_class_str(&self, escape: bool, with_surrogates: bool) -> Option<String> {
        match self {
            Token::Literal(c) => {
                if escape && *c as u32 > 127 {
                    None // can't put escaped in char class
                } else {
                    Some(escape_char_in_class(*c))
                }
            }
            Token::MultiChar(s) => {
                if escape {
                    None
                } else {
                    Some(s.chars().map(|c| escape_char_in_class(c)).collect())
                }
            }
            Token::Digit => None,
            Token::NonDigit => None,
            Token::Space => None,
            Token::NonSpace => None,
            Token::Word => None,
            Token::NonWord => None,
        }
    }

    pub fn is_literal(&self) -> bool {
        matches!(self, Token::Literal(_) | Token::MultiChar(_))
    }

    pub fn literal_char(&self) -> Option<char> {
        match self {
            Token::Literal(c) => Some(*c),
            _ => None,
        }
    }
}

pub fn char_to_escape(c: char, with_surrogates: bool) -> String {
    let cp = c as u32;
    if with_surrogates && cp >= 0x10000 {
        // Convert to surrogate pair
        let cp = cp - 0x10000;
        let high = 0xD800 + (cp >> 10);
        let low = 0xDC00 + (cp & 0x3FF);
        format!("\\u{{{:x}}}\\u{{{:x}}}", high, low)
    } else {
        format!("\\u{{{:x}}}", cp)
    }
}

pub fn escape_regex_char(c: char) -> String {
    match c {
        '.' | '+' | '*' | '?' | '^' | '$' | '{' | '}' | '[' | ']' | '(' | ')' | '|' | '\\' => {
            format!("\\{}", c)
        }
        '-' => "\\-".to_string(),
        _ => c.to_string(),
    }
}

pub fn escape_char_in_class(c: char) -> String {
    match c {
        ']' | '\\' | '^' => format!("\\{}", c),
        '-' => "\\-".to_string(),
        _ => c.to_string(),
    }
}

/// Classify a character into a token based on options
pub fn classify_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> Token {
    let is_digit = is_unicode_digit(c);
    let is_space = c.is_whitespace();
    let is_word = c.is_alphanumeric() || c == '_';

    if digits && is_digit {
        Token::Digit
    } else if spaces && is_space {
        Token::Space
    } else if words && is_word {
        Token::Word
    } else if non_digits && !is_digit {
        Token::NonDigit
    } else if non_spaces && !is_space {
        Token::NonSpace
    } else if non_words && !is_word {
        Token::NonWord
    } else {
        Token::Literal(c)
    }
}

/// Check if a char is a Unicode decimal digit
pub fn is_unicode_digit(c: char) -> bool {
    // Unicode category Nd (decimal digit numbers)
    // This includes ASCII 0-9 and digits from other scripts
    matches!(c, '0'..='9') || 
