/// A DFA state
#[derive(Debug, Clone)]
pub struct State {
    pub transitions: BTreeMap<Token, usize>,
    pub is_accepting: bool,
}

impl State {
    pub fn new(is_accepting: bool) -> Self {
        State {
            transitions: BTreeMap::new(),
            is_accepting,
        }
    }
}

/// A Deterministic Finite Automaton
pub struct DFA {
    pub states: Vec<State>,
    pub initial: usize,
}

impl DFA {
    pub fn new() -> Self {
        DFA {
            states: vec![State::new(false)],
            initial: 0,
        }
    }

    pub fn add_state(&mut self, is_accepting: bool) -> usize {
        let id = self.states.len();
        self.states.push(State::new(is_accepting));
        id
    }

    pub fn add_transition(&mut self, from: usize, token: Token, to: usize) {
        self.states[from].transitions.insert(token, to);
    }

    pub fn set_accepting(&mut self, state: usize) {
        self.states[state].is_accepting = true;
    }

    /// Build DFA from a list of token sequences
    pub fn from_token_sequences(sequences: &[Vec<Token>]) -> Self {
        let mut dfa = DFA::new();

        for seq in sequences {
            let mut current = dfa.initial;
            for token in seq {
                let next = if let Some(&next) = dfa.states[current].transitions.get(token) {
                    next
                } else {
                    let new_state = dfa.add_state(false);
                    dfa.states[current].transitions.insert(token.clone(), new_state);
                    new_state
                };
                current = next;
            }
            dfa.set_accepting(current);
        }

        dfa
    }

    /// Minimize the DFA using Hopcroft's algorithm
    pub fn minimize(&self) -> Self {
        let n = self.states.len();
        if n == 0 {
            return DFA::new();
        }

        // Partition states into accepting and non-accepting
        let accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| self.states[s].is_accepting)
            .collect();
        let non_accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| !self.states[s].is_accepting)
            .collect();

        let mut partition: Vec<BTreeSet<usize>> = Vec::new();
        if !accepting.is_empty() {
            partition.push(accepting);
        }
        if !non_accepting.is_empty() {
            partition.push(non_accepting);
        }
        if partition.is_empty() {
            partition.push(BTreeSet::new());
        }

        // Collect all tokens in the DFA
        let all_tokens: BTreeSet<Token> = self.states.iter()
            .flat_map(|s| s.transitions.keys().cloned())
            .collect();

        let mut worklist: VecDeque<BTreeSet<usize>> = partition.iter().cloned().collect();

        loop {
            let mut new_partition: Vec<BTreeSet<usize>> = Vec::new();
            let mut changed = false;

            for group in &partition {
                if group.len() <= 1 {
                    new_partition.push(group.clone());
                    continue;
                }

                // Try to split this group
                let mut split = false;
                for token in &all_tokens {
                    // Group states by which partition class they transition to under 'token'
                    let mut groups_by_dest: BTreeMap<Option<usize>, BTreeSet<usize>> = BTreeMap::new();

                    for &state in group {
                        let dest = self.states[state].transitions.get(token).copied();
                        // Find which partition class the dest belongs to
                        let dest_class = if let Some(d) = dest {
                            // Find the index of the partition class containing d
                            partition.iter().position(|g| g.contains(&d))
                        } else {
                            None
                        };
                        groups_by_dest.entry(dest_class).or_default().insert(state);
                    }

                    if groups_by_dest.len() > 1 {
                        // This token splits the group
                        for (_, sub_group) in groups_by_dest {
                            new_partition.push(sub_group);
                        }
                        split = true;
                        changed = true;
                        break;
                    }
                }

                if !split {
                    new_partition.push(group.clone());
                }
            }

            partition = new_partition;
            if !changed {
                break;
            }
        }

        // Build the minimized DFA
        // Find which partition each state belongs to
        let state_to_partition: Vec<usize> = (0..n)
            .map(|s| partition.iter().position(|g| g.contains(&s)).unwrap_or(0))
            .collect();

        let initial_partition = state_to_partition[self.initial];

        // Create new states, one per partition
        let mut new_dfa = DFA {
            states: partition.iter().map(|g| {
                let is_accepting = g.iter().any(|&s| self.states[s].is_accepting);
                State::new(is_accepting)
            }).collect(),
            initial: initial_partition,
        };

        // Add transitions
        for (pi, group) in partition.iter().enumerate() {
            let representative = *group.iter().next().unwrap();
            for (token, &dest) in &self.states[representative].transitions {
                let dest_partition = state_to_partition[dest];
                new_dfa.states[pi].transitions.insert(token.clone(), dest_partition);
            }
        }

        new_dfa
    }
}
