use std::collections::{BTreeMap, BTreeSet};
use crate::cli::Config;
use crate::dfa::{Token, DFA, classify_char, escape_regex_char, escape_char_in_class, char_to_escape};

/// Segment Unicode string into grapheme clusters
/// Simple approximation - handles combining characters
fn grapheme_clusters(s: &str) -> Vec<String> {
    let mut clusters: Vec<String> = Vec::new();
    let mut chars = s.chars().peekable();

    while let Some(c) = chars.next() {
        let mut cluster = c.to_string();
        // Check for combining characters (category M in Unicode)
        while let Some(&next) = chars.peek() {
            if is_combining_char(next) {
                cluster.push(next);
                chars.next();
            } else {
                break;
            }
        }
        clusters.push(cluster);
    }

    clusters
}

fn is_combining_char(c: char) -> bool {
    let cp = c as u32;
    // Unicode combining character ranges (Mn, Mc, Me categories - simplified)
    matches!(cp,
        0x0300..=0x036F |   // Combining Diacritical Marks
        0x1DC0..=0x1DFF |   // Combining Diacritical Marks Supplement
        0x20D0..=0x20FF |   // Combining Diacritical Marks for Symbols
        0xFE20..=0xFE2F |   // Combining Half Marks
        0x0483..=0x0489 |
