/// Build a character class string from a sorted list of chars
pub fn build_char_class(chars: &[char]) -> String {
    if chars.is_empty() {
        return String::new();
    }
    if chars.len() == 1 {
        return escape_regex_char(chars[0]);
    }

    // Build ranges
    let mut ranges: Vec<CharRange> = Vec::new();
    let mut start = chars[0];
    let mut end = chars[0];

    for &c in &chars[1..] {
        if c as u32 == end as u32 + 1 {
            end = c;
        } else {
            ranges.push(CharRange { start, end });
            start = c;
            end = c;
        }
    }
    ranges.push(CharRange { start, end });

    // Build char class string
    let mut class_content = String::new();
    for range in &ranges {
        let len = range.end as u32 - range.start as u32 + 1;
        if len == 1 {
            class_content.push_str(&escape_char_in_class(range.start));
        } else if len == 2 {
            class_content.push_str(&escape_char_in_class(range.start));
            class_content.push_str(&escape_char_in_class(range.end));
        } else {
            // Range
            class_content.push_str(&escape_char_in_class(range.start));
            class_content.push('-');
            class_content.push_str(&escape_char_in_class(range.end));
        }
    }

    format!("[{}]", class_content)
}

