/// Check if a regex string is a "single unit" (doesn't need grouping for quantifiers)
pub fn is_single_unit(r: &str) -> bool {
    if r.len() == 1 {
        return true;
    }

    let chars: Vec<char> = r.chars().collect();

    // Escaped char: \x
    if chars[0] == '\\' && chars.len() == 2 {
        return true;
    }

    // Unicode escape: \u{...}
    if r.starts_with("\\u{") && r.ends_with('}') {
        return true;
    }

    // Character class: [...]
    if chars[0] == '[' {
        let mut depth = 0;
        for c in &chars {
            match c {
                '[' => depth += 1,
                ']' => {
                    depth -= 1;
                    if depth == 0 {
                        return r.ends_with(']') && chars.last() == Some(&']');
                    }
                }
                _ => {}
            }
        }
    }

    // Non-capturing group: (?:...)
    if r.starts_with("(?:") {
        let mut depth = 0;
        let mut i = 0;
        let bytes = r.as_bytes();
        while i < bytes.len() {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == bytes.len() - 1;
                    }
                }
                b'\\' => i += 1,
                _ => {}
            }
            i += 1;
        }
    }

    // Capturing group: (...)
    if r.starts_with('(') && !r.starts_with("(?") {
        let mut depth = 0;
        let mut i = 0;
        let bytes = r.as_bytes();
        while i < bytes.len() {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == bytes.len() - 1;
                    }
                }
                b'\\' => i += 1,
                _ => {}
            }
            i += 1;
        }
    }

    // (?i) prefix
    if r.starts_with("(?i)") {
        return true;
    }

    false
}

