        result.push_str(&format_verbose(&body, cfg));
    } else {
        result.push_str(&body);
    }

    // End anchor
    if !cfg.no_anchors && !cfg.no_end_anchor {
        result.push('$');
    }

    result
}

fn format_verbose(body: &str, cfg: &Config) -> String {
    // Parse the regex body and format it with proper indentation
    // This is complex - we need to understand the structure
    format_regex_verbose(body, cfg)
}

/// Convert DFA to regular expression using state elimination (Brzozowski's method)
fn dfa_to_regex(dfa: &DFA, cfg: &Config) -> String {
    let n = dfa.states.len();

    // We'll use the generalized NFA (GNFA) approach with state elimination
    // Create a GNFA with n+2 states: 0..n are original states, n is new initial, n+1 is new final

    // Build a matrix of regex expressions between states
    // regex[i][j] = the regex pattern for transitions from state i to state j

    let new_init = n;
    let new_final = n + 1;
    let total = n + 2;

    let mut regex_matrix: Vec<Vec<Option<String>>> = vec![vec![None; total]; total];

    // Add epsilon from new_init to dfa.initial
    regex_matrix[new_init][dfa.initial] = Some(String::new()); // epsilon

    // Add original transitions
    for (i, state) in dfa.states.iter().enumerate() {
        // Group transitions to same destination
        let mut dest_to_tokens: BTreeMap<usize, Vec<&Token>> = BTreeMap::new();
        for (token, &dest) in &state.transitions {
            dest_to_tokens.entry(dest).or_default().push(token);
        }

        for (dest, tokens) in dest_to_tokens {
            let pattern = tokens_to_pattern(&tokens, cfg);
            regex_matrix[i][dest] = Some(pattern);
        }

        // If accepting, add transition to new final
        if state.is_accepting {
            regex_matrix[i][new_final] = Some(String::new()); // epsilon
        }
    }

    // Eliminate states one by one (all except new_init and new_final)
    // Eliminate states that are not new_init or new_final
    let mut active_states: Vec<usize> = (0..n).collect();
    active_states.push(new_init);
    active_states.push(new_final);

    // Order: eliminate original states first
    for elim in 0..n {
        // Eliminate state 'elim'
        // For each pair (i, j) where i and j are not 'elim':
        // regex[i][j] = regex[i][j] | regex[i][elim] . regex[elim][elim]* . regex[elim][j]

        let loop_pat = regex_matrix[elim][elim].clone();
        let loop_regex = loop_pat.map(|p| {
            if p.is_empty() {
                // Self-loop with epsilon - this creates (ε)* = empty
                None
            } else {
                Some(make_star(&p))
            }
        }).flatten();

        // Collect all incoming and outgoing edges for 'elim'
        let incoming: Vec<usize> = (0..total)
            .filter(|&i| i != elim && regex_matrix[i][elim].is_some())
            .collect();
        let outgoing: Vec<usize> = (0..total)
            .filter(|&j| j != elim && regex_matrix[elim][j].is_some())
            .collect();

        for &i in &incoming {
            for &j in &outgoing {
                if i == j { continue; } // Skip self-loops (we'll handle separately if needed)

                let in_pat = regex_matrix[i][elim].clone().unwrap();
                let out_pat = regex_matrix[elim][j].clone().unwrap();

                let new_path = if let Some(ref lp) = loop_regex {
                    concat_regex(&concat_regex(&in_pat, lp), &out_pat)
                } else {
                    concat_regex(&in_pat, &out_pat)
                };

                let existing = regex_matrix[i][j].take();
                regex_matrix[i][j] = Some(if let Some(ex) = existing {
                    alternate_regex(&ex, &new_path)
                } else {
                    new_path
                });
            }
        }

        // Remove transitions involving 'elim'
        for row in regex_matrix.iter_mut() {
            row[elim] = None;
        }
        for col in 0..total {
            regex_matrix[elim][col] = None;
        }
    }

    // The result is regex_matrix[new_init][new_final]
    regex_matrix[new_init][new_final].clone().unwrap_or_default()
}

/// Convert a list of tokens to a regex pattern (character class or alternation)
fn tokens_to_pattern(tokens: &[&Token], cfg: &Config) -> String {
    if tokens.len() == 1 {
        return tokens[0].to_regex_str(cfg.escape, cfg.with_surrogates);
    }

    // Check if all tokens are literal characters that can form a character class
    let all_literals: Vec<Option<(char, String)>> = tokens.iter().map(|t| {
        match t {
            Token::Literal(c) => {
                if cfg.escape && *c as u32 > 127 {
                    None // escaped char can't be in char class
                } else {
                    Some((*c, escape_char_in_class(*c)))
                }
            }
            _ => None,
        }
    }).collect();

    let has_non_literal = all_literals.iter().any(|x| x.is_none());
    let has_literal = all_literals.iter().any(|x| x.is_some());

    if !has_non_literal {
        // All are literals - build a character class
        let mut chars: Vec<char> = all_literals.iter()
            .map(|x| x.as_ref().unwrap().0)
            .collect();
        chars.sort();
        chars.dedup();

        return build_char_class(&chars);
    }

    // Mixed or all non-literals - use alternation
    // Separate literals from non-literals
    let mut literal_chars: Vec<char> = Vec::new();
    let mut non_literal_pats: Vec<String> = Vec::new();

    for (t, literal_opt) in tokens.iter().zip(all_literals.iter()) {
        if let Some((c, _)) = literal_opt {
            literal_chars.push(*c);
        } else {
            non_literal_pats.push(t.to_regex_str(cfg.escape, cfg.with_surrogates));
        }
    }

    // Sort and deduplicate
    literal_chars.sort();
    literal_chars.dedup();
    non_literal_pats.sort();
    non_literal_pats.dedup();

    let mut parts: Vec<String> = non_literal_pats;

    if literal_chars.len() == 1 {
        parts.push(escape_regex_char(literal_chars[0]));
    } else if literal_chars.len() > 1 {
        parts.push(build_char_class(&literal_chars));
    }

    if parts.len() == 1 {
        parts.into_iter().next().unwrap()
    } else {
        // alternation - but we need to decide on grouping
        // For transitions between two states, we put in an alternation
        parts.join("|")
    }
}

/// Build a character class string from a sorted list of chars
pub fn build_char_class(chars: &[char]) -> String {
    if chars.is_empty() {
        return String::new();
    }
    if chars.len() == 1 {
        return escape_regex_char(chars[0]);
    }

    // Build ranges
    let mut ranges: Vec<CharRange> = Vec::new();
    let mut start = chars[0];
    let mut end = chars[0];

    for &c in &chars[1..] {
        if c as u32 == end as u32 + 1 {
            end = c;
        } else {
            ranges.push(CharRange { start, end });
            start = c;
            end = c;
        }
    }
    ranges.push(CharRange { start, end });

    // Build char class string
    let mut class_content = String::new();
    for range in &ranges {
        let len = range.end as u32 - range.start as u32 + 1;
        if len == 1 {
            class_content.push_str(&escape_char_in_class(range.start));
        } else if len == 2 {
            class_content.push_str(&escape_char_in_class(range.start));
            class_content.push_str(&escape_char_in_class(range.end));
        } else {
            // Range
            class_content.push_str(&escape_char_in_class(range.start));
            class_content.push('-');
            class_content.push_str(&escape_char_in_class(range.end));
        }
    }

    format!("[{}]", class_content)
}

struct CharRange {
    start: char,
    end: char,
}

/// Make a star quantifier: r* or (?:r)*
pub fn make_star(r: &str) -> String {
    if r.is_empty() {
        return String::new(); // epsilon* = epsilon
    }
    if is_single_unit(r) {
        format!("{}*", r)
    } else {
        format!("(?:{})*", r)
    }
}

/// Make a plus quantifier: r+
pub fn make_plus(r: &str) -> String {
    if r.is_empty() {
        return String::new();
    }
    if is_single_unit(r) {
        format!("{}+", r)
    } else {
        format!("(?:{})+", r)
    }
}

/// Make optional: r?
pub fn make_optional(r: &str, use_capturing: bool) -> String {
    if r.is_empty() {
        return String::new();
    }
    if is_single_unit(r) {
        format!("{}?", r)
    } else {
        if use_capturing {
            format!("({})?", r)
        } else {
            format!("(?:{})?", r)
        }
    }
}

/// Concatenate two regex patterns
pub fn concat_regex(a: &str, b: &str) -> String {
    if a.is_empty() {
        return b.to_string();
    }
    if b.is_empty() {
        return a.to_string();
    }
    format!("{}{}", a, b)
}

/// Alternate two regex patterns: a|b or (?:a|b) 
pub fn alternate_regex(a: &str, b: &str) -> String {
    if a.is_empty() && b.is_empty() {
        return String::new();
    }
    if a == b {
        return a.to_string();
    }
    // Use alternation without grouping at this level
    format!("{}|{}", a, b)
}

/// Check if a regex string is a "single unit" (doesn't need grouping for quantifiers)
pub fn is_single_unit(r: &str) -> bool {
    if r.len() == 1 {
        return true;
    }

    let chars: Vec<char> = r.chars().collect();

    // Escaped char: \x
    if chars[0] == '\\' && chars.len() == 2 {
        return true;
    }

    // Unicode escape: \u{...}
    if r.starts_with("\\u{") && r.ends_with('}') {
        return true;
    }

    // Character class: [...]
    if chars[0] == '[' {
        let mut depth = 0;
        for c in &chars {
            match c {
                '[' => depth += 1,
                ']' => {
                    depth -= 1;
                    if depth == 0 {
                        return r.ends_with(']') && chars.last() == Some(&']');
                    }
                }
                _ => {}
            }
        }
    }

    // Non-capturing group: (?:...)
    if r.starts_with("(?:") {
        let mut depth = 0;
        let mut i = 0;
        let bytes = r.as_bytes();
        while i < bytes.len() {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == bytes.len() - 1;
                    }
                }
                b'\\' => i += 1,
                _ => {}
            }
            i += 1;
        }
    }

    // Capturing group: (...)
    if r.starts_with('(') && !r.starts_with("(?") {
        let mut depth = 0;
        let mut i = 0;
        let bytes = r.as_bytes();
        while i < bytes.len() {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == bytes.len() - 1;
                    }
                }
                b'\\' => i += 1,
                _ => {}
            }
            i += 1;
        }
    }

    // (?i) prefix
    if r.starts_with("(?i)") {
        return true;
    }

    false
}

/// Format regex in verbose mode
fn format_regex_verbose(body: &str, cfg: &Config) -> String {
    parse_and_format(body, 0, cfg)
}

fn parse_and_format(body: &str, indent: usize, cfg: &Config) -> String {
    let indent_str = "  ".repeat(indent);
    let inner_indent_str = "  ".repeat(indent + 1);

    // Find the top-level structure
    // If it's a single alternation at top level: (?:a|b|c) -> format as group with alternations
    // If it contains a non-capturing group at top level

    // Simple approach: find top-level alternations and handle groups
    let formatted = format_node(body, indent, cfg);
    formatted
}

fn format_node(expr: &str, indent: usize, _cfg: &Config) -> String {
    // Format a regex expression as verbose
    let indent_str = "  ".repeat(indent);

    // Check if it's empty
    if expr.is_empty() {
        return String::new();
    }

    // Try to parse and format
    format_expr_verbose(expr, indent)
}

fn format_expr_verbose(expr: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    // Try to expand group structure
    let bytes = expr.as_bytes();
    let mut result = String::new();
    let mut i = 0;

    // Find top-level pieces
    let pieces = split_top_level(expr);

    if pieces.len() == 1 {
        // Single piece - check if it's a group
        let piece = &pieces[0];

        if piece.starts_with("(?:") && piece.ends_with(')') {
            // Non-capturing group
            let inner = &piece[3..piece.len()-1];
            let inner_formatted = format_group_contents(inner, indent);
            return inner_formatted;
        }

        // Just return as-is with proper indentation
        return format!("{}{}", spaces, piece);
    }

    // Multiple pieces - concatenation
    let mut out = String::new();
    for piece in &pieces {
        let formatted = format_single_piece(piece, indent);
        out.push_str(&formatted);
        out.push('\n');
    }

    if out.ends_with('\n') {
        out.pop();
    }
    out
}

fn format_group_contents(inner: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);
    let inner_spaces = "  ".repeat(indent + 1);

    // Split by top-level alternations
    let alts = split_top_level_alternations(inner);

    if alts.len() == 1 {
        // No top-level alternation - just a sequence
        let pieces = split_top_level(&alts[0]);
        let mut out = String::new();
        out.push_str(&format!("{}(?:\n", spaces));
        for piece in &pieces {
            let formatted = format_single_piece_inner(piece, indent + 1);
            out.push_str(&formatted);
            out.push('\n');
        }
        // Remove trailing newline
        if out.ends_with('\n') { out.pop(); }
        out.push('\n');
        out.push_str(&format!("{})", spaces));
        return out;
    }

    // Multiple alternatives
    let mut out = String::new();
    out.push_str(&format!("{}(?:\n", spaces));
    for (idx, alt) in alts.iter().enumerate() {
        let formatted = format_single_piece_inner(alt, indent + 1);
        out.push_str(&formatted);
        if idx < alts.len() - 1 {
            out.push('\n');
            out.push_str(&format!("{inner_spaces}|\n", inner_spaces = "  ".repeat(indent + 1)));
        }
    }
    out.push('\n');
    out.push_str(&format!("{})", spaces));
    out
}

fn format_single_piece(piece: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    // Check for quantified group
    if piece.ends_with(')') || piece.ends_with(")?") || piece.ends_with(")+") {
        // Handle quantified groups
    }

    // Handle a piece which could be: literal, [class], (?:...), (?:...){n}, etc.
    format_piece_with_quantifier(piece, indent)
}

fn format_single_piece_inner(piece: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);
    format_piece_with_quantifier(piece, indent)
}

fn format_piece_with_quantifier(piece: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    // Extract quantifier from end
    let (base, quant) = extract_quantifier(piece);

    if quant.is_empty() {
        // No quantifier - check if it's a group or simple atom
        if (base.starts_with("(?:") || base.starts_with("(?i:") ) && base.ends_with(')') {
            let inner = &base[3..base.len()-1];
            let alts = split_top_level_alternations(inner);
            if alts.len() > 1 || inner.contains("(?:") {
                // Multi-level: expand
                let mut out = String::new();
                out.push_str(&format!("{}(?:\n", spaces));
                for (idx, alt) in alts.iter().enumerate() {
                    // Format each alternative
                    let alt_formatted = format_alternative(alt, indent + 1);
                    out.push_str(&alt_formatted);
                    if idx < alts.len() - 1 {
                        out.push('\n');
                        out.push_str(&format!("{spaces}  |\n", spaces = spaces));
                    }
                }
                out.push('\n');
                out.push_str(&format!("{})", spaces));
                return out;
            }
        }
        // Simple atom - just indent it
        return format!("{}{}", spaces, base);
    }

    // Has quantifier - if base is a group, expand it
    if (base.starts_with("(?:") && base.ends_with(')')) {
        let inner = &base[3..base.len()-1];
        let alts = split_top_level_alternations(inner);
        if alts.len() > 1 || needs_expansion(inner) {
            let mut out = String::new();
            out.push_str(&format!("{}(?:\n", spaces));
            for (idx, alt) in alts.iter().enumerate() {
                let alt_formatted = format_alternative(alt, indent + 1);
                out.push_str(&alt_formatted);
                if idx < alts.len() - 1 {
                    out.push('\n');
                    out.push_str(&format!("{spaces}  |\n", spaces = spaces));
                }
            }
            out.push('\n');
            out.push_str(&format!("{}){}", spaces, quant));
            return out;
        }
    }

    // Simple atom with quantifier
    format!("{}{}{}", spaces, base, quant)
}

fn needs_expansion(s: &str) -> bool {
    s.contains("(?:")
}

fn format_alternative(alt: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    // Split into pieces
    let pieces = split_concatenation(alt);

    if pieces.len() == 1 {
        return format_piece_with_quantifier(&pieces[0], indent);
    }

    let mut out = String::new();
    for piece in &pieces {
        let formatted = format_piece_with_quantifier(piece, indent);
        out.push_str(&formatted);
        out.push('\n');
    }
    if out.ends_with('\n') { out.pop(); }
    out
}

/// Split an expression into top-level concatenated pieces
fn split_concatenation(s: &str) -> Vec<String> {
    let mut pieces = Vec::new();
    let mut current = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut depth = 0;

    while i < bytes.len() {
        match bytes[i] {
            b'(' => {
                depth += 1;
                current.push(bytes[i] as char);
            }
            b')' => {
                depth -= 1;
                current.push(bytes[i] as char);
                if depth == 0 {
                    // Check for quantifier
                    let j = i + 1;
                    if j < bytes.len() && matches!(bytes[j], b'?' | b'+' | b'*' | b'{') {
                        let (quant, skip) = read_quantifier(&s[j..]);
                        current.push_str(&quant);
                        i += skip;
                    }
                    if !current.is_empty() {
                        pieces.push(current.clone());
                        current.clear();
                    }
                }
            }
            b'[' if depth == 0 => {
                depth += 1;
                current.push(bytes[i] as char);
            }
            b']' if depth == 1 => {
                depth -= 1;
                current.push(bytes[i] as char);
                if depth == 0 {
                    let j = i + 1;
                    if j < bytes.len() && matches!(bytes[j], b'?' | b'+' | b'*' | b'{') {
                        let (quant, skip) = read_quantifier(&s[j..]);
                        current.push_str(&quant);
                        i += skip;
                    }
                    pieces.push(current.clone());
                    current.clear();
                }
            }
            b'\\' if depth == 0 => {
                current.push('\\');
                i += 1;
                if i < bytes.len() {
                    if bytes[i] == b'u' {
                        // \u{...}
                        current.push('u');
                        i += 1;
                        while i < bytes.len() && bytes[i] != b'}' {
                            current.push(bytes[i] as char);
                            i += 1;
                        }
                        if i < bytes.len() {
                            current.push('}');
                        }
                    } else {
                        current.push(bytes[i] as char);
                    }
                    // Check for quantifier after escape
                    let j = i + 1;
                    if j < bytes.len() && matches!(bytes[j], b'?' | b'+' | b'*' | b'{') {
                        let (quant, skip) = read_quantifier(&s[j..]);
                        current.push_str(&quant);
                        i += skip;
                    }
                    pieces.push(current.clone());
                    current.clear();
                }
            }
            _ if depth == 0 => {
                current.push(bytes[i] as char);
                // Check for quantifier after simple char
                let j = i + 1;
                if j < bytes.len() && matches!(bytes[j], b'?' | b'+' | b'*' | b'{') && depth == 0 {
                    let (quant, skip) = read_quantifier(&s[j..]);
                    current.push_str(&quant);
                    i += skip;
                }
                pieces.push(current.clone());
                current.clear();
            }
            _ => {
                current.push(bytes[i] as char);
            }
        }
        i += 1;
    }

    if !current.is_empty() {
        pieces.push(current);
    }

    pieces
}

fn read_quantifier(s: &str) -> (String, usize) {
    let bytes = s.as_bytes();
    if bytes.is_empty() { return (String::new(), 0); }

    match bytes[0] {
        b'?' | b'+' | b'*' => (String::from_utf8_lossy(&bytes[0..1]).to_string(), 1),
        b'{' => {
            let end = s.find('}').unwrap_or(0);
            if end > 0 {
                (s[..=end].to_string(), end + 1)
            } else {
                (String::new(), 0)
            }
        }
        _ => (String::new(), 0),
    }
}

/// Split top-level pieces (concatenation units)
fn split_top_level(expr: &str) -> Vec<String> {
    split_concatenation(expr)
}

/// Split by top-level alternations (|)
fn split_top_level_alternations(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut depth = 0;

    while i < bytes.len() {
        match bytes[i] {
            b'(' | b'[' => {
                depth += 1;
                current.push(bytes[i] as char);
            }
            b')' | b']' => {
                depth -= 1;
                current.push(bytes[i] as char);
            }
            b'|' if depth == 0 => {
                parts.push(current.clone());
                current.clear();
            }
            b'\\' => {
                current.push('\\');
                i += 1;
                if i < bytes.len() {
                    current.push(bytes[i] as char);
                }
            }
            _ => {
                current.push(bytes[i] as char);
            }
        }
        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    if parts.is_empty() {
        parts.push(s.to_string());
    }

    parts
}

/// Extract quantifier from end of expression
fn extract_quantifier(s: &str) -> (&str, &str) {
    let bytes = s.as_bytes();
    let len = bytes.len();

    if len == 0 {
        return (s, "");
    }

    // Check for {n,m} or {n} at end
    if bytes[len-1] == b'}' {
        if let Some(brace_start) = s.rfind('{') {
            // Make sure we're not inside a char class
            let before = &s[..brace_start];
            if !is_inside_char_class(before) {
                return (&s[..brace_start], &s[brace_start..]);
            }
        }
    }

    // Check for ?, +, * at end
    match bytes[len-1] {
        b'?' | b'+' | b'*' => {
            (&s[..len-1], &s[len-1..])
        }
        _ => (s, "")
    }
}

fn is_inside_char_class(s: &str) -> bool {
    let mut in_class = false;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'[' => in_class = true,
            b']' => in_class = false,
            b'\\' => i += 1,
            _ => {}
        }
        i += 1;
    }
    in_class
}

/// Apply repetition conversion if -r flag is set
