    if r.starts_with("(?:") {
        let mut depth = 0;
        let mut i = 0;
        let bytes = r.as_bytes();
        while i < bytes.len() {
            match bytes[i] {
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == bytes.len() - 1;
                    }
                }
                b'\\' => i += 1,
                _ => {}
            }
            i += 1;
        }
    }

    // Capturing group: (...)
    if r.starts_with('(') && !r.starts_with("(?") {
        let mut depth = 0;
