            if !is_inside_char_class(before) {
                return (&s[..brace_start], &s[brace_start..]);
            }
        }
    }

    // Check for ?, +, * at end
    match bytes[len-1] {
        b'?' | b'+' | b'*' => {
            (&s[..len-1], &s[len-1..])
        }
        _ => (s, "")
    }
}

fn is_inside_char_class(s: &str) -> bool {
    let mut in_class = false;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'[' => in_class = true,
            b']' => in_class = false,
            b'\\' => i += 1,
            _ => {}
        }
        i += 1;
    }
    in_class
}

