/// Convert input string to token sequence
fn string_to_tokens(s: &str, cfg: &Config) -> Vec<Token> {
    let clusters = grapheme_clusters(s);
    let mut tokens = Vec::new();

    for cluster in clusters {
        let chars: Vec<char> = cluster.chars().collect();
        if chars.len() == 1 {
            tokens.push(classify_char(chars[0], cfg.digits, cfg.non_digits, 
                                      cfg.spaces, cfg.non_spaces, cfg.words, cfg.non_words));
        } else {
            // Multi-char grapheme cluster
            let first_token = classify_char(chars[0], cfg.digits, cfg.non_digits,
                                            cfg.spaces, cfg.non_spaces, cfg.words, cfg.non_words);
            if first_token.is_literal() {
                tokens.push(Token::MultiChar(cluster));
            } else {
                for c in chars {
                    tokens.push(classify_char(c, cfg.digits, cfg.non_digits,
                                              cfg.spaces, cfg.non_spaces, cfg.words, cfg.non_words));
                }
            }
        }
    }

    tokens
}

/// Build the regexp
pub fn build_regexp(test_cases: &[String], cfg: &Config) -> String {
    // Filter empty strings
    let non_empty: Vec<&String> = test_cases.iter().filter(|s| !s.is_empty()).collect();

    if non_empty.is_empty() {
        return format_result("", cfg);
    }

    // Convert to token sequences
    let mut sequences: Vec<Vec<Token>> = non_empty.iter()
        .map(|s| string_to_tokens(s, cfg))
        .collect();

    // Deduplicate
    sequences.sort();
    sequences.dedup();

    // Apply repetition detection if needed
    if cfg.repetitions {
        sequences = sequences.into_iter()
            .map(|seq| detect_repetitions(seq, cfg.min_repetitions, cfg.min_substring_length))
            .collect();
    }

    // Build DFA
    let dfa = DFA::from_token_sequences(&sequences);

    // Minimize DFA
    let min_dfa = dfa.minimize();

    // Convert to regex
    let body = dfa_to_regex_string(&min_dfa, cfg);

    format_result(&body, cfg)
}

