}

fn consume_quantifier(bytes: &[u8], mut i: usize, n: usize) -> usize {
    if i >= n {
        return i;
    }
    match bytes[i] {
        b'?' | b'+' | b'*' => i + 1,
        b'{' => {
            let start = i;
            i += 1;
            while i < n && bytes[i] != b'}' {
                i += 1;
            }
            if i < n { i + 1 } else { start }
        }
        _ => i,
    }
}

fn find_matching_paren(bytes: &[u8], start: usize) -> usize {
    let mut depth = 0;
    let mut i = start;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 { return i; }
            }
            _ => {}
        }
        i += 1;
    }
    bytes.len() - 1
}

fn find_matching_bracket(bytes: &[u8], start: usize) -> usize {
    let mut i = start + 1; // skip opening [
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b']' => return i,
            _ => {}
        }
        i += 1;
    }
    bytes.len() - 1
}

/// Split by top-level | alternation
fn split_by_alternation(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut depth = 0;

    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                current.push('\\');
                i += 1;
                if i < bytes.len() {
                    current.push(bytes[i] as char);
                }
            }
            b'(' | b'[' => {
                depth += 1;
                current.push(bytes[i] as char);
            }
            b')' | b']' => {
                depth -= 1;
                current.push(bytes[i] as char);
            }
            b'|' if depth == 0 => {
                parts.push(current.clone());
                current.clear();
            }
            _ => {
                current.push(bytes[i] as char);
            }
        }
        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }
    if parts.is_empty() {
        parts.push(s.to_string());
    }
    parts
}

