/// Convert DFA to regex string
fn dfa_to_regex_string(dfa: &DFA, cfg: &Config) -> String {
    let n = dfa.states.len();

    if n == 0 {
        return String::new();
    }

    // Use state elimination (GNFA method)
    // States: 0..n are original, n = new_init, n+1 = new_final
