    }
}

/// Build a path from in_str . star_str? . out_str
fn build_path(in_str: &str, star_str: Option<&str>, out_str: &str) -> String {
    let mut parts = Vec::new();

    if !in_str.is_empty() {
        parts.push(in_str.to_string());
    }
    if let Some(s) = star_str {
        if !s.is_empty() {
            parts.push(s.to_string());
        }
    }
    if !out_str.is_empty() {
        parts.push(out_str.to_string());
    }

    parts.join("")
}

/// Create alternation of two regex strings
fn alternate_strings(a: &str, b: &str) -> String {
    if a.is_empty() && b.is_empty() {
        return String::new();
    }
    if a == b {
        return a.to_string();
    }
    // Return alternation - will be wrapped in group when needed
    format!("{}|{}", a, b)
}

/// Create star of a regex string (wrap in group if needed)
fn make_star_str(r: &str) -> String {
    if r.is_empty() {
        return String::new();
    }
    if is_single_regex_unit(r) {
        format!("{}*", r)
    } else {
        format!("(?:{})*", r)
    }
}

#[derive(Debug, Clone)]
enum RegexAtom {
    Epsilon,
    Str(String),
}

impl RegexAtom {
    fn to_regex(&self, cfg: &Config) -> String {
        match self {
            RegexAtom::Epsilon => String::new(),
            RegexAtom::Str(s) => s.clone(),
        }
    }
}

fn combine_atoms(target: &mut Option<RegexAtom>, new: RegexAtom) {
    *target = match target.take() {
        None => Some(new),
        Some(existing) => {
            match (existing, new) {
                (RegexAtom::Epsilon, RegexAtom::Epsilon) => Some(RegexAtom::Epsilon),
                (RegexAtom::Epsilon, RegexAtom::Str(s)) |
                (RegexAtom::Str(s), RegexAtom::Epsilon) => {
                    // alternation of epsilon and s... = s?
                    // Actually this shouldn't happen for transitions from same source
                    Some(RegexAtom::Str(s))
                }
                (RegexAtom::Str(a), RegexAtom::Str(b)) => {
                    if a == b {
                        Some(RegexAtom::Str(a))
                    } else {
                        Some(RegexAtom::Str(format!("{}|{}", a, b)))
                    }
                }
            }
        }
    };
}

/// Convert a list of tokens to a regex atom (for a single DFA transition)
fn tokens_to_atom(tokens: Vec<&Token>, cfg: &Config) -> RegexAtom {
    if tokens.is_empty() {
        return RegexAtom::Epsilon;
    }

    if tokens.len() == 1 {
        let s = token_to_regex_str(tokens[0], cfg);
        return RegexAtom::Str(s);
    }

    // Multiple tokens on the same transition = character class
    let s = build_token_class(&tokens, cfg);
    RegexAtom::Str(s)
}

/// Convert a token to its regex string representation
pub fn token_to_regex_str(token: &Token, cfg: &Config) -> String {
    match token {
        Token::Literal(c) => {
            if cfg.escape && *c as u32 > 127 {
                char_to_escape(*c, cfg.with_surrogates)
            } else {
                escape_regex_char(*c)
            }
        }
        Token::MultiChar(s) => {
            if cfg.escape {
                s.chars().map(|c| {
                    if c as u32 > 127 {
                        char_to_escape(c, cfg.with_surrogates)
                    } else {
                        escape_regex_char(c)
                    }
                }).collect()
            } else {
                s.chars().map(|c| escape_regex_char(c)).collect()
            }
        }
        Token::Digit => "\\d".to_string(),
        Token::NonDigit => "\\D".to_string(),
        Token::Space => "\\s".to_string(),
        Token::NonSpace => "\\S".to_string(),
        Token::Word => "\\w".to_string(),
        Token::NonWord => "\\W".to_string(),
    }
}

/// Build a character class or alternation from multiple tokens
fn build_token_class(tokens: &[&Token], cfg: &Config) -> String {
    // Separate literal chars from class tokens
    let mut literal_chars: Vec<char> = Vec::new();
    let mut class_tokens: Vec<String> = Vec::new();

    for tok in tokens {
        match tok {
            Token::Literal(c) => {
                if cfg.escape && *c as u32 > 127 {
                    // Can't put in char class when escaped
                    class_tokens.push(char_to_escape(*c, cfg.with_surrogates));
                } else {
                    literal_chars.push(*c);
                }
            }
            Token::MultiChar(s) => {
                // Multi-char can't go in char class
                if cfg.escape {
                    class_tokens.push(s.chars().map(|c| {
                        if c as u32 > 127 {
                            char_to_escape(c, cfg.with_surrogates)
                        } else {
                            escape_regex_char(c)
                        }
                    }).collect());
                } else {
                    class_tokens.push(s.chars().map(|c| escape_regex_char(c)).collect());
                }
            }
            _ => {
                class_tokens.push(token_to_regex_str(tok, cfg));
            }
        }
    }

    literal_chars.sort();
    literal_chars.dedup();

    let mut parts: Vec<String> = Vec::new();

    // Add class tokens
    for ct in &class_tokens {
        if !parts.contains(ct) {
            parts.push(ct.clone());
        }
    }

    // Build char class from literals
    if literal_chars.len() == 1 {
        parts.push(escape_regex_char(literal_chars[0]));
    } else if literal_chars.len() > 1 {
        parts.push(build_char_class(&literal_chars));
    }

    if parts.len() == 1 {
        return parts.into_iter().next().unwrap();
    }

    // Multiple parts: alternation
    parts.join("|")
}

/// Build a character class from sorted chars
pub fn build_char_class(chars: &[char]) -> String {
    if chars.is_empty() {
        return String::new();
    }
    if chars.len() == 1 {
        return escape_regex_char(chars[0]);
    }

    // Build consecutive ranges
    let mut content = String::new();
    let mut start = chars[0];
    let mut end = chars[0];

    for &c in &chars[1..] {
        if c as u32 == end as u32 + 1 {
            end = c;
        } else {
            append_range(&mut content, start, end);
            start = c;
            end = c;
        }
    }
    append_range(&mut content, start, end);

    format!("[{}]", content)
}

fn append_range(s: &mut String, start: char, end: char) {
    let len = end as u32 - start as u32 + 1;
    match len {
        1 => s.push_str(&escape_char_in_class(start)),
        2 => {
            s.push_str(&escape_char_in_class(start));
            s.push_str(&escape_char_in_class(end));
        }
        _ => {
            s.push_str(&escape_char_in_class(start));
            s.push('-');
            s.push_str(&escape_char_in_class(end));
        }
    }
}

/// Check if a regex string is a "single unit" that doesn't need parentheses for quantifiers
pub fn is_single_regex_unit(s: &str) -> bool {
    if s.is_empty() {
        return true;
    }

    let bytes = s.as_bytes();
    let n = bytes.len();

    // Single char (not special)
    if n == 1 {
        return true;
    }

    // Escape sequence
    if bytes[0] == b'\\' {
        // \u{...}
        if n >= 4 && bytes[1] == b'u' && bytes[2] == b'{' && bytes[n-1] == b'}' {
            // Check it's just one escape
            let content = &s[3..n-1];
            if !content.contains('{') {
                return true;
            }
        }
        if n == 2 {
            return true;
        }
    }

    // Character class [...]
    if bytes[0] == b'[' {
        let mut depth = 0;
        let mut i = 0;
        while i < n {
            match bytes[i] {
                b'\\' => i += 1,
                b'[' => depth += 1,
                b']' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == n - 1;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        return false;
    }

    // Group (...) or (?:...)
    if bytes[0] == b'(' {
        let mut depth = 0;
        let mut i = 0;
        while i < n {
            match bytes[i] {
                b'\\' => i += 1,
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return i == n - 1;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        return false;
    }

    false
}

/// Wrap regex in non-capturing group if it has top-level alternation
pub fn maybe_group(s: &str, capture: bool) -> String {
    if has_top_level_alternation(s) {
        if capture {
            format!("({})", s)
        } else {
            format!("(?:{})", s)
        }
    } else {
        s.to_string()
    }
}

/// Check if a regex string has a top-level alternation
pub fn has_top_level_alternation(s: &str) -> bool {
    let bytes = s.as_bytes();
    let mut depth = 0;
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b'(' | b'[' => depth += 1,
            b')' | b']' => depth -= 1,
            b'|' if depth == 0 => return true,
            _ => {}
        }
        i += 1;
    }
    false
}

fn format_result(body: &str, cfg: &Config) -> String {
    // Determine what we need to wrap
    let needs_wrap = has_top_level_alternation(body);

    let wrapped_body = if needs_wrap {
        maybe_group(body, cfg.capture_groups)
    } else {
        body.to_string()
    };

    let mut result = String::new();

    if cfg.ignore_case {
        result.push_str("(?i)");
    }

    let start = !cfg.no_anchors && !cfg.no_start_anchor;
    let end = !cfg.no_anchors && !cfg.no_end_anchor;

    if cfg.verbose {
        // Verbose mode
        let mut verbose_parts = Vec::new();

        if cfg.ignore_case {
            // (?i) is at the start
        }

        // We need to format the wrapped body in verbose mode
        let verbose_body = format_verbose_body(&wrapped_body, 1);

        let mut out = String::new();
        out.push_str("(?x)\n");
        if start {
            out.push_str("^\n");
        }
        out.push_str(&verbose_body);
        out.push('\n');
        if end {
            out.push('$');
        }

        return out;
    }

    if start {
        result.push('^');
    }
    result.push_str(&wrapped_body);
    if end {
        result.push('$');
    }

    result
}

/// Format a regex body for verbose mode
fn format_verbose_body(body: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    if body.is_empty() {
        return String::new();
    }

    // Check if it's a non-capturing group
    if body.starts_with("(?:") && body.ends_with(')') {
        // Check that the closing ) is the last char
        let inner = &body[3..body.len()-1];
        if is_balanced_group(body) {
            return format_group_verbose(inner, indent);
        }
    }

    // Check if it's a quantified non-capturing group: (?:...){n} etc
    let (base, quant) = split_quantifier(body);
    if !quant.is_empty() && base.starts_with("(?:") && base.ends_with(')') {
        let inner = &base[3..base.len()-1];
        if is_balanced_group(base) {
            let inner_fmt = format_group_verbose(inner, indent);
            // Add quantifier on closing paren line
            // inner_fmt ends with "spaces)"
            // We need to add quant to the last line
            let mut lines: Vec<&str> = inner_fmt.split('\n').collect();
            if let Some(last) = lines.last_mut() {
                // This is tricky with &str - let me just append
                let mut out = inner_fmt.clone();
                out.push_str(quant);
                return out;
            }
        }
    }

    // Just return with indentation
    // Split by concat pieces
    let pieces = split_concat_pieces(body);

    if pieces.len() == 1 {
        return format!("{}{}", spaces, body);
    }

    // Multiple pieces - format each on its own line
    let mut out = String::new();
    for (i, piece) in pieces.iter().enumerate() {
        let formatted = format_piece_verbose(piece, indent);
        if i > 0 { out.push('\n'); }
        out.push_str(&formatted);
    }
    out
}

fn format_group_verbose(inner: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);
    let inner_spaces = "  ".repeat(indent + 1);

    // Split by top-level alternations
    let alts = split_by_alternation(inner);

    if alts.len() == 1 {
        // No alternation - check if there are groups inside
        let pieces = split_concat_pieces(&alts[0]);
        if pieces.len() == 1 && !needs_verbose_expansion(&pieces[0]) {
            // Simple single piece - just inline
            return format!("{}(?:\n{}{}\n{})", spaces, inner_spaces, &alts[0], spaces);
        }
        // Multiple pieces or complex piece
        let mut out = String::new();
        out.push_str(&format!("{}(?:\n", spaces));
        for piece in &pieces {
            let formatted = format_piece_verbose(piece, indent + 1);
            out.push_str(&formatted);
            out.push('\n');
        }
        if out.ends_with('\n') { out.pop(); }
        out.push('\n');
        out.push_str(&format!("{})", spaces));
        return out;
    }

    // Multiple alternatives
    let mut out = String::new();
    out.push_str(&format!("{}(?:\n", spaces));
    for (i, alt) in alts.iter().enumerate() {
        let formatted = format_alt_verbose(alt, indent + 1);
        out.push_str(&formatted);
        if i < alts.len() - 1 {
            out.push('\n');
            out.push_str(&format!("{inner_spaces}|\n", inner_spaces = inner_spaces));
        }
    }
    out.push('\n');
    out.push_str(&format!("{})", spaces));
    out
}

fn format_alt_verbose(alt: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);
    let pieces = split_concat_pieces(alt);

    if pieces.len() == 1 {
        return format_piece_verbose(&pieces[0], indent);
    }

    let mut out = String::new();
    for (i, piece) in pieces.iter().enumerate() {
        let formatted = format_piece_verbose(piece, indent);
        if i > 0 { out.push('\n'); }
        out.push_str(&formatted);
    }
    out
}

fn format_piece_verbose(piece: &str, indent: usize) -> String {
    let spaces = "  ".repeat(indent);

    // Check for quantified non-capturing group
    let (base, quant) = split_quantifier(piece);

    if !base.is_empty() && base.starts_with("(?:") && base.ends_with(')') && is_balanced_group(base) {
        let inner = &base[3..base.len()-1];
        let inner_fmt = format_group_verbose(inner, indent);
        let mut result = inner_fmt;
        result.push_str(quant);
        return result;
    }

    if !base.is_empty() && needs_verbose_expansion(base) {
        if base.starts_with("(?:") && base.ends_with(')') && is_balanced_group(base) {
            let inner = &base[3..base.len()-1];
            let inner_fmt = format_group_verbose(inner, indent);
            let mut result = inner_fmt;
            result.push_str(quant);
            return result;
        }
    }

    // Simple piece
    format!("{}{}", spaces, piece)
}

fn needs_verbose_expansion(s: &str) -> bool {
    s.contains("(?:")
}

/// Check if a string is a balanced group (matching parens from start)
fn is_balanced_group(s: &str) -> bool {
    let bytes = s.as_bytes();
    if bytes.is_empty() || bytes[0] != b'(' { return false; }
    let mut depth = 0;
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 {
                    return i == bytes.len() - 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    false
}

/// Split a regex into (base, quantifier)
fn split_quantifier(s: &str) -> (&str, &str) {
    let bytes = s.as_bytes();
    let n = bytes.len();

    if n == 0 { return (s, ""); }

    // Find the end of the quantifier from the right
    // Quantifiers: ?, +, *, {n}, {n,m}, {n,}

    if bytes[n-1] == b'}' {
        if let Some(pos) = rfind_brace_start(s) {
            // Check it's not inside a character class or group
            let base = &s[..pos];
            let quant = &s[pos..];
            if is_valid_quantifier(quant) {
                return (base, quant);
            }
        }
    }

    match bytes[n-1] {
        b'?' | b'+' | b'*' => {
            // Make sure it's not escaped
            if n >= 2 && bytes[n-2] == b'\\' {
                return (s, "");
            }
            (&s[..n-1], &s[n-1..])
        }
        _ => (s, "")
    }
}

fn rfind_brace_start(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = bytes.len();
    while i > 0 {
        i -= 1;
        if bytes[i] == b'{' {
            return Some(i);
        }
        if !matches!(bytes[i], b'0'..=b'9' | b',' | b'}') {
            return None;
        }
    }
    None
}

fn is_valid_quantifier(s: &str) -> bool {
    if !s.starts_with('{') || !s.ends_with('}') {
        return false;
    }
    let inner = &s[1..s.len()-1];
    // Should be n or n,m or n,
    inner.chars().all(|c| c.is_ascii_digit() || c == ',')
}

/// Split a concatenation into individual pieces
/// e.g., "ab(?:cd)?e" -> ["a", "b", "(?:cd)?", "e"]
fn split_concat_pieces(s: &str) -> Vec<String> {
    let mut pieces = Vec::new();
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut i = 0;

    while i < n {
        let piece_start = i;

        match bytes[i] {
            b'\\' => {
                // Escape sequence
                i += 1;
                if i < n {
                    if bytes[i] == b'u' && i+1 < n && bytes[i+1] == b'{' {
                        // \u{...}
                        while i < n && bytes[i] != b'}' {
                            i += 1;
                        }
                        if i < n { i += 1; } // consume '}'
                    } else {
                        i += 1; // consume escaped char
                    }
                }
                // Check for quantifier
                i = consume_quantifier(bytes, i, n);
                pieces.push(s[piece_start..i].to_string());
            }
            b'(' => {
                // Group
                let group_end = find_matching_paren(bytes, i);
                i = group_end + 1;
                // Check for quantifier
                i = consume_quantifier(bytes, i, n);
                pieces.push(s[piece_start..i].to_string());
            }
            b'[' => {
                // Character class
                let class_end = find_matching_bracket(bytes, i);
                i = class_end + 1;
                // Check for quantifier
                i = consume_quantifier(bytes, i, n);
                pieces.push(s[piece_start..i].to_string());
            }
            _ => {
                i += 1;
                // Check for quantifier
                i = consume_quantifier(bytes, i, n);
                pieces.push(s[piece_start..i].to_string());
            }
        }
    }

    pieces
}

fn consume_quantifier(bytes: &[u8], mut i: usize, n: usize) -> usize {
    if i >= n {
        return i;
    }
    match bytes[i] {
        b'?' | b'+' | b'*' => i + 1,
        b'{' => {
            let start = i;
            i += 1;
            while i < n && bytes[i] != b'}' {
                i += 1;
            }
            if i < n { i + 1 } else { start }
        }
        _ => i,
    }
}

fn find_matching_paren(bytes: &[u8], start: usize) -> usize {
    let mut depth = 0;
    let mut i = start;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 { return i; }
            }
            _ => {}
        }
        i += 1;
    }
    bytes.len() - 1
}

fn find_matching_bracket(bytes: &[u8], start: usize) -> usize {
    let mut i = start + 1; // skip opening [
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 1,
            b']' => return i,
            _ => {}
        }
        i += 1;
    }
    bytes.len() - 1
}

/// Split by top-level | alternation
fn split_by_alternation(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut depth = 0;

    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                current.push('\\');
                i += 1;
                if i < bytes.len() {
                    current.push(bytes[i] as char);
                }
            }
            b'(' | b'[' => {
                depth += 1;
                current.push(bytes[i] as char);
            }
            b')' | b']' => {
                depth -= 1;
                current.push(bytes[i] as char);
            }
            b'|' if depth == 0 => {
                parts.push(current.clone());
                current.clear();
            }
            _ => {
                current.push(bytes[i] as char);
            }
        }
        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }
    if parts.is_empty() {
        parts.push(s.to_string());
    }
    parts
}

