/// Factor out common prefix from alternations: prefix(a|b) = prefix + (a|b)
/// Factor out common suffix from alternations: (a|b)suffix
/// These transformations simplify the regex

/// Split a regex into (prefix, rest) where prefix is the common prefix
/// of all top-level alternatives
pub fn factor_prefix(s: &str) -> String {
    let alts = split_alternations(s);
    if alts.len() <= 1 {
        return s.to_string();
    }

    // Find common prefix of all alternatives
    let prefix = common_prefix(&alts);
    if prefix.is_empty() {
        // Try suffix factoring
        return factor_suffix_of_alts(&alts);
    }

    // Remove prefix from each alternative
    let suffixes: Vec<String> = alts.iter()
        .map(|a| a[prefix.len()..].to_string())
        .collect();

    // Recursively process the suffixes
    let suffix_regex = if suffixes.iter().all(|s| s.is_empty()) {
        String::new()
    } else {
        let processed: Vec<String> = suffixes.iter()
            .filter(|s| !s.is_empty())
            .cloned()
            .collect();
        if processed.is_empty() {
            String::new()
        } else if processed.len() == 1 {
            processed.into_iter().next().unwrap()
        } else {
            // Some suffixes are empty (meaning prefix alone is acceptable)
            let has_empty = suffixes.iter().any(|s| s.is_empty());
            let non_empty: Vec<String> = suffixes.iter()
                .filter(|s| !s.is_empty())
                .cloned()
                .collect();

            let combined = if non_empty.len() == 1 {
                non_empty.into_iter().next().unwrap()
            } else {
                let factored = factor_suffix_of_alts(&non_empty);
                factored
            };

            if has_empty {
                make_optional_str(&combined)
            } else {
                make_group_if_needed(&combined)
            }
        }
    };

    format!("{}{}", prefix, suffix_regex)
}

fn factor_suffix_of_alts(alts: &[String]) -> String {
    // Find common suffix
    let suffix = common_suffix(alts);
    if suffix.is_empty() {
        // No common suffix - check if all are single chars -> char class
        if alts.iter().all(|a| is_single_char_pattern(a)) {
            // Build character class
            let chars: Vec<char> = alts.iter()
                .flat_map(|a| unescape_single_char(a))
                .collect();
            let mut chars = chars;
            chars.sort();
            chars.dedup();
            return build_char_class_from_chars(&chars);
        }

        // Just join with |
        let joined = alts.join("|");
        return joined;
    }

    // Remove suffix from each alternative
    let prefixes: Vec<String> = alts.iter()
        .map(|a| {
            let len = a.len() - suffix.len();
            a[..len].to_string()
        })
        .collect();

    // Process the prefixes
    let has_empty = prefixes.iter().any(|p| p.is_empty());
    let non_empty: Vec<String> = prefixes.iter()
        .filter(|p| !p.is_empty())
        .cloned()
        .collect();

    let prefix_regex = if non_empty.is_empty() {
        String::new()
    } else {
        let prefix_str = if non_empty.len() == 1 {
            non_empty.into_iter().next().unwrap()
        } else {
            // Recursively factor the prefixes
            let joined = non_empty.join("|");
            factor_prefix(&joined)
        };

        if has_empty {
            make_optional_str(&prefix_str)
        } else {
            make_group_if_needed(&prefix_str)
        }
    };

    format!("{}{}", prefix_regex, suffix)
}

fn make_optional_str(s: &str) -> String {
    if s.is_empty() { return String::new(); }
    if is_single_regex_unit_str(s) {
        format!("{}?", s)
    } else {
        format!("(?:{})?", s)
    }
}

fn make_group_if_needed(s: &str) -> String {
    if has_top_level_alternation_str(s) {
        format!("(?:{})", s)
    } else {
        s.to_string()
    }
}

fn is_single_char_pattern(s: &str) -> bool {
    let bytes = s.as_bytes();
    if bytes.len() == 1 && !is_special(bytes[0] as char) {
        return true;
    }
    // Escaped special char: \.
    if bytes.len() == 2 && bytes[0] == b'\\' {
        return true;
    }
    false
}

fn unescape_single_char(s: &str) -> Option<char> {
    let bytes = s.as_bytes();
    if bytes.len() == 1 {
        return Some(bytes[0] as char);
    }
    if bytes.len() == 2 && bytes[0] == b'\\' {
        return Some(bytes[1] as char);
    }
