use std::collections::BTreeMap;
use crate::dfa::{Token, DFA};
use crate::cli::Config;
use crate::regex::{
    token_to_regex_str, build_char_class, is_single_regex_unit, 
    has_top_level_alternation, maybe_group
};
use crate::factor::factor_regex;

/// Generate regex from a minimized DFA using recursive suffix approach
pub fn generate_regex(dfa: &DFA, cfg: &Config) -> String {
    let n = dfa.states.len();
    if n == 0 {
        return String::new();
    }

    // Compute topological order (for DAG DFA)
    let topo = topological_sort(dfa);

    // Compute suffix regex for each state in reverse topological order
    let mut suffix: Vec<String> = vec![String::new(); n];

    for &state in topo.iter().rev() {
        suffix[state] = compute_suffix(dfa, state, &suffix, cfg);
    }

    suffix[dfa.initial].clone()
}

fn topological_sort(dfa: &DFA) -> Vec<usize> {
    let n = dfa.states.len();
    let mut visited = vec![false; n];
    let mut order = Vec::new();

    fn dfs(state: usize, dfa: &DFA, visited: &mut Vec<bool>, order: &mut Vec<usize>) {
        if visited[state] { return; }
        visited[state] = true;
        for &next in dfa.states[state].transitions.values() {
            if !visited[next] {
                dfs(next, dfa, visited, order);
            }
        }
        order.push(state);
    }

    dfs(dfa.initial, dfa, &mut visited, &mut order);
    order.reverse();
    order
}

fn compute_suffix(dfa: &DFA, state: usize, suffix: &[String], cfg: &Config) -> String {
    let state_obj = &dfa.states[state];
    let is_accepting = state_obj.is_accepting;

    if state_obj.transitions.is_empty() {
        return String::new(); // epsilon (accepting) or dead
    }

    // Group transitions by destination state suffix
    // Transitions to states with the same suffix can be combined
    let mut by_dest_suffix: BTreeMap<String, Vec<&Token>> = BTreeMap::new();

    for (token, &dest) in &state_obj.transitions {
        let dest_suf = suffix[dest].clone();
        by_dest_suffix.entry(dest_suf).or_default().push(token);
    }

    // Build one alternative per unique destination suffix
    let mut alternatives: Vec<String> = Vec::new();

    for (dest_suffix, tokens) in &by_dest_suffix {
        let token_pattern = build_token_pattern(tokens, cfg);

        let alt = if dest_suffix.is_empty() {
            token_pattern
        } else {
            format!("{}{}", token_pattern, dest_suffix)
        };

        alternatives.push(alt);
    }

    // Now try to factor/simplify the alternatives
    // Sort for determinism
    alternatives.sort_by(|a, b| compare_alternatives(a, b));

    let combined = if alternatives.len() == 1 {
        alternatives.into_iter().next().unwrap()
    } else {
        // Try factoring first
        let joined = alternatives.join("|");
        factor_regex(&joined)
    };

    // If accepting, make the combined part optional
    if is_accepting && !combined.is_empty() {
        make_optional(&combined, cfg)
    } else {
        combined
    }
}

fn compare_alternatives(a: &str, b: &str) -> std::cmp::Ordering {
    // Sort: prefer longer alternatives first, then alphabetical
    // This matches grex's output ordering
    b.len().cmp(&a.len()).then(a.cmp(b))
}

fn make_optional(s: &str, cfg: &Config) -> String {
    if s.is_empty() {
        return String::new();
    }

    if is_single_regex_unit(s) {
        format!("{}?", s)
    } else {
        if cfg.capture_groups {
            format!("({})?", s)
        } else {
            format!("(?:{})?", s)
        }
    }
}

fn build_token_pattern(tokens: &[&Token], cfg: &Config) -> String {
    if tokens.is_empty() {
        return String::new();
    }

    if tokens.len() == 1 {
        return token_to_regex_str(tokens[0], cfg);
    }

    // Multiple tokens -> character class or alternation
    let mut literal_chars: Vec<char> = Vec::new();
    let mut non_literal_pats: Vec<String> = Vec::new();

    for &tok in tokens {
        match tok {
            Token::Literal(c) => {
                if cfg.escape && *c as u32 > 127 {
                    non_literal_pats.push(crate::dfa::char_to_escape(*c, cfg.with_surrogates));
                } else {
                    literal_chars.push(*c);
                }
            }
            _ => {
                non_literal_pats.push(token_to_regex_str(tok, cfg));
            }
        }
    }

    literal_chars.sort();
    literal_chars.dedup();

    let literal_pat = if literal_chars.len() == 1 {
        Some(crate::dfa::escape_regex_char(literal_chars[0]))
    } else if literal_chars.len() > 1 {
        Some(build_char_class(&literal_chars))
    } else {
        None
    };

    let mut parts: Vec<String> = non_literal_pats;
    parts.sort();
    parts.dedup();
    if let Some(lp) = literal_pat {
        parts.push(lp);
    }

    if parts.len() == 1 {
        parts.into_iter().next().unwrap()
    } else {
        parts.join("|")
    }
}
