use std::collections::{BTreeMap, BTreeSet, VecDeque};

/// A token representing a character or character class in a DFA transition
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Token {
    Literal(char),
    MultiChar(String), // For multi-codepoint grapheme clusters
    Digit,             // \d
    NonDigit,          // \D
    Space,             // \s
    NonSpace,          // \S
    Word,              // \w
    NonWord,           // \W
    // Repetition group: inner tokens repeated (min..=max) times
    // Used as a single DFA transition token
    RepeatGroup(Vec<Token>, usize, usize), // (inner, min_count, max_count)
}

impl Token {
    pub fn is_literal(&self) -> bool {
        matches!(self, Token::Literal(_) | Token::MultiChar(_))
    }

    pub fn literal_char(&self) -> Option<char> {
        match self {
            Token::Literal(c) => Some(*c),
            _ => None,
        }
    }

    pub fn is_repeat_group(&self) -> bool {
        matches!(self, Token::RepeatGroup(_, _, _))
    }
}

pub fn char_to_escape(c: char, with_surrogates: bool) -> String {
    let cp = c as u32;
    if with_surrogates && cp >= 0x10000 {
        let cp = cp - 0x10000;
        let high = 0xD800 + (cp >> 10);
        let low = 0xDC00 + (cp & 0x3FF);
        format!("\\u{{{:x}}}\\u{{{:x}}}", high, low)
    } else {
        format!("\\u{{{:x}}}", cp)
    }
}

pub fn escape_regex_char(c: char) -> String {
    match c {
        '.' | '+' | '*' | '?' | '^' | '$' | '{' | '}' | '[' | ']' | '(' | ')' | '|' | '\\' => {
            format!("\\{}", c)
        }
        '-' => "\\-".to_string(),
        _ => c.to_string(),
    }
}

pub fn escape_char_in_class(c: char) -> String {
    match c {
        ']' | '\\' | '^' => format!("\\{}", c),
        '-' => "\\-".to_string(),
        _ => c.to_string(),
    }
}

pub fn classify_char(c: char, digits: bool, non_digits: bool, spaces: bool, non_spaces: bool, words: bool, non_words: bool) -> Token {
    let is_digit = is_unicode_digit(c);
    let is_space = c.is_whitespace();
    let is_word = c.is_alphanumeric() || c == '_';

    if digits && is_digit {
        Token::Digit
    } else if spaces && is_space {
        Token::Space
    } else if words && is_word {
        Token::Word
    } else if non_digits && !is_digit {
        Token::NonDigit
    } else if non_spaces && !is_space {
        Token::NonSpace
    } else if non_words && !is_word {
        Token::NonWord
    } else {
        Token::Literal(c)
    }
}

pub fn is_unicode_digit(c: char) -> bool {
    matches!(c, '0'..='9') || 
    matches!(c as u32, 
        0x0660..=0x0669 | 0x06F0..=0x06F9 | 0x07C0..=0x07C9 | 0x0966..=0x096F |
        0x09E6..=0x09EF | 0x0A66..=0x0A6F | 0x0AE6..=0x0AEF | 0x0B66..=0x0B6F |
        0x0BE6..=0x0BEF | 0x0C66..=0x0C6F | 0x0CE6..=0x0CEF | 0x0D66..=0x0D6F |
        0x0DE6..=0x0DEF | 0x0E50..=0x0E59 | 0x0ED0..=0x0ED9 | 0x0F20..=0x0F29 |
        0x1040..=0x1049 | 0x1090..=0x1099 | 0x17E0..=0x17E9 | 0x1810..=0x1819 |
        0x1946..=0x194F | 0x19D0..=0x19D9 | 0x1A80..=0x1A89 | 0x1A90..=0x1A99 |
        0x1B50..=0x1B59 | 0x1BB0..=0x1BB9 | 0x1C40..=0x1C49 | 0x1C50..=0x1C59 |
        0xA620..=0xA629 | 0xA8D0..=0xA8D9 | 0xA900..=0xA909 | 0xA9D0..=0xA9D9 |
        0xA9F0..=0xA9F9 | 0xAA50..=0xAA59 | 0xABF0..=0xABF9 | 0xFF10..=0xFF19
    )
}

#[derive(Debug, Clone)]
pub struct State {
    pub transitions: BTreeMap<Token, usize>,
    pub is_accepting: bool,
}

impl State {
    pub fn new(is_accepting: bool) -> Self {
        State {
            transitions: BTreeMap::new(),
            is_accepting,
        }
    }
}

pub struct DFA {
    pub states: Vec<State>,
    pub initial: usize,
}

impl DFA {
    pub fn new() -> Self {
        DFA {
            states: vec![State::new(false)],
            initial: 0,
        }
    }

    pub fn add_state(&mut self, is_accepting: bool) -> usize {
        let id = self.states.len();
        self.states.push(State::new(is_accepting));
        id
    }

    pub fn set_accepting(&mut self, state: usize) {
        self.states[state].is_accepting = true;
    }

    pub fn from_token_sequences(sequences: &[Vec<Token>]) -> Self {
        let mut dfa = DFA::new();

        for seq in sequences {
            let mut current = dfa.initial;
            for token in seq {
                let next = if let Some(&next) = dfa.states[current].transitions.get(token) {
                    next
                } else {
                    let new_state = dfa.add_state(false);
                    dfa.states[current].transitions.insert(token.clone(), new_state);
                    new_state
                };
                current = next;
            }
            dfa.set_accepting(current);
        }

        dfa
    }

    pub fn minimize(&self) -> Self {
        let n = self.states.len();
        if n == 0 {
            return DFA::new();
        }

        let accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| self.states[s].is_accepting)
            .collect();
        let non_accepting: BTreeSet<usize> = (0..n)
            .filter(|&s| !self.states[s].is_accepting)
            .collect();

        let mut partition: Vec<BTreeSet<usize>> = Vec::new();
        if !accepting.is_empty() {
            partition.push(accepting);
        }
        if !non_accepting.is_empty() {
            partition.push(non_accepting);
        }
        if partition.is_empty() {
            partition.push(BTreeSet::new());
        }

        let all_tokens: BTreeSet<Token> = self.states.iter()
            .flat_map(|s| s.transitions.keys().cloned())
            .collect();

        loop {
            let mut new_partition: Vec<BTreeSet<usize>> = Vec::new();
            let mut changed = false;

            for group in &partition {
                if group.len() <= 1 {
                    new_partition.push(group.clone());
                    continue;
                }

                let mut split = false;
                for token in &all_tokens {
                    let mut groups_by_dest: BTreeMap<Option<usize>, BTreeSet<usize>> = BTreeMap::new();

                    for &state in group {
                        let dest = self.states[state].transitions.get(token).copied();
                        let dest_class = dest.map(|d| {
                            partition.iter().position(|g| g.contains(&d))
                        }).flatten();
                        groups_by_dest.entry(dest_class).or_default().insert(state);
                    }

                    if groups_by_dest.len() > 1 {
                        for (_, sub_group) in groups_by_dest {
                            new_partition.push(sub_group);
                        }
                        split = true;
                        changed = true;
                        break;
                    }
                }

                if !split {
                    new_partition.push(group.clone());
                }
            }

            partition = new_partition;
            if !changed {
                break;
            }
        }

        let state_to_partition: Vec<usize> = (0..n)
            .map(|s| partition.iter().position(|g| g.contains(&s)).unwrap_or(0))
            .collect();

        let initial_partition = state_to_partition[self.initial];

        let mut new_dfa = DFA {
            states: partition.iter().map(|g| {
                let is_accepting = g.iter().any(|&s| self.states[s].is_accepting);
                State::new(is_accepting)
            }).collect(),
            initial: initial_partition,
        };

        for (pi, group) in partition.iter().enumerate() {
            let representative = *group.iter().next().unwrap();
            for (token, &dest) in &self.states[representative].transitions {
                let dest_partition = state_to_partition[dest];
                new_dfa.states[pi].transitions.insert(token.clone(), dest_partition);
            }
        }

        new_dfa
    }
}
