                    } else if !ends_at_end && b_ends {
                        false
                    } else if count > b_count {
                        true // prefer higher count
                    } else if count < b_count {
                        false
                    } else if start > b_start {
                        true // prefer rightmost start
                    } else if start < b_start {
                        false
                    } else {
                        period > b_period // prefer longer period
                    }
                }
            };

            if better {
                best = Some((start, period, count, ends_at_end));
