    let base = first_base.clone();

    // Collect all counts and sort them
    let mut count_ranges: Vec<(usize, usize)> = bases.iter()
        .map(|(_, min, max)| (*min, *max))
        .collect();
    count_ranges.sort_by_key(|(min, _)| *min);

    // Merge adjacent/overlapping ranges
