# The problem: in the default case "_ => { i += 1; }", it increments by 1 BYTE.
# But for a multi-byte Unicode character like "ì" (2 bytes: 0xCC 0x8C for U+0306),
# we need to advance by the full character width.
# 
# When processing "y̆" (= 'y' + combining breve '\u0306'):
# y = 1 byte, combining breve = 2 bytes (UTF-8: 0xCC 0x86)
# Actually wait: combining breve is U+0306, UTF-8: CC 86 (2 bytes)
# "y̆" = y (1 byte) + combining breve (2 bytes) = 3 bytes total
# 
# In split_into_units, when we process "y̆":
# i=0: 'y' (byte 0x79), not special -> i += 1 -> i=1, unit_start=0, unit=[y]
# Then i=1: byte 0xCC, not special -> i += 1 -> i=2
# Then s[0..2] -> tries to slice at byte 2 but "y̆" at byte 2 is inside the combining char!
# 
# Fix: when encountering a non-ASCII byte, advance by the full UTF-8 character width.
# OR: process the string char by char instead of byte by byte.

cat > /tmp/fix_units.py << 'EOF'
with open('grex_impl/src/factor.rs', 'r') as f:
    content = f.read()

old = '''            _ => {
                i += 1;
                i = consume_quant(bytes, i, n);
            }
        }

        units.push(s[unit_start..i].to_string());'''

new = '''            _ => {
                // Handle multi-byte UTF-8 characters
                let c = s[i..].chars().next().unwrap_or('\\0');
                i += c.len_utf8();
                i = consume_quant(bytes, i, n);
            }
        }

        // Make sure we're at a char boundary
        while i < n && !s.is_char_boundary(i) { i += 1; }
        units.push(s[unit_start..i].to_string());'''

content = content.replace(old, new, 1)  # Only replace first occurrence in split_into_units
with open('grex_impl/src/factor.rs', 'w') as f:
    f.write(content)
print("Done")
EOF
