# The fix: in split_alternations and similar byte-iterating functions in factor.rs,
# handle multi-byte chars properly.
# The issue: when we see a non-ASCII byte, we need to push the FULL char, not the byte.
# 
# The simplest fix: in the default case in split_alternations, advance by char boundaries.

cat > /tmp/fix_split_alt.py << 'EOF'
with open('grex_impl/src/factor.rs', 'r') as f:
    content = f.read()

# Fix split_alternations
old = '''/// Split a regex by top-level | alternation
fn split_alternations(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut depth = 0;

    while i < bytes.len() {
        match bytes[i] {
            b\'\\\\' => {
                current.push('\\\\');
                i += 1;
                if i < bytes.len() { current.push(bytes[i] as char); }
            }
            b\'(\' | b\'[\' => { depth += 1; current.push(bytes[i] as char); }
            b\')\' | b\']\' => { depth -= 1; current.push(bytes[i] as char); }
            b\'|\' if depth == 0 => {
                parts.push(current.clone());
                current.clear();
            }
            _ => { current.push(bytes[i] as char); }
        }
        i += 1;
    }

    if !current.is_empty() { parts.push(current); }
    if parts.is_empty() { parts.push(s.to_string()); }
    parts
}'''

