    while i < bytes.len() {
        match bytes[i] {
            b\'\\\\' => {
                current.push(\'\\\\');
                i += 1;
                if i < bytes.len() {
                    // Push the full char after backslash
                    let c = s[i..].chars().next().unwrap_or(\'\\0\');
                    current.push(c);
                    i += c.len_utf8();
                    continue;
