/// Advanced factoring: groups alternatives by their last unit and factors common suffixes
/// This handles cases like ["hello", "world", "foo"] -> "(?:hell|fo)o|world"
pub fn factor_by_last_unit(alts: &[String]) -> String {
    if alts.is_empty() { return String::new(); }
    if alts.len() == 1 { return alts[0].clone(); }

    // First try quantifier merging
    if let Some(merged) = try_merge_quantifiers(alts) {
        return merged;
    }

    // Group alternatives by their last unit
    use std::collections::HashMap;
    let mut by_last_unit: Vec<(String, Vec<String>)> = Vec::new(); // (last_unit, prefixes)
    let mut order: Vec<String> = Vec::new(); // track order of last_units
    let mut last_unit_to_idx: HashMap<String, usize> = HashMap::new();

    for alt in alts {
        let units = split_into_units(alt);
        if units.is_empty() { continue; }
        let last = units.last().unwrap().clone();
        let prefix: String = units[..units.len()-1].join("");

        if let Some(&idx) = last_unit_to_idx.get(&last) {
            by_last_unit[idx].1.push(prefix);
        } else {
            let idx = by_last_unit.len();
            last_unit_to_idx.insert(last.clone(), idx);
            by_last_unit.push((last.clone(), vec![prefix]));
            order.push(last);
        }
    }

    // Build result
    let mut result_parts: Vec<String> = Vec::new();

    for (last_unit, prefixes) in &by_last_unit {
        if prefixes.len() == 1 {
            // Only one alternative ends with this unit - no factoring needed
            if prefixes[0].is_empty() {
                result_parts.push(last_unit.clone());
            } else {
                result_parts.push(format!("{}{}", prefixes[0], last_unit));
            }
        } else {
            // Multiple alternatives end with this unit - factor it
            let has_empty = prefixes.iter().any(|p| p.is_empty());
            let non_empty: Vec<String> = prefixes.iter().filter(|p| !p.is_empty()).cloned().collect();

            if non_empty.is_empty() {
                // All prefixes are empty -> just last_unit
                result_parts.push(last_unit.clone());
            } else {
                // Recursively factor the prefixes
                let combined_prefix = factor_by_last_unit(&non_empty);

                if has_empty {
                    // Some alternatives are just last_unit, others are prefix+last_unit
                    // -> "last_unit?" or "(prefix?)last_unit"
                    let prefix_group = make_optional_str(&combined_prefix);
                    result_parts.push(format!("{}{}", prefix_group, last_unit));
                } else {
                    // All alternatives have non-empty prefix
                    let prefix_group = make_group_if_needed(&combined_prefix);
                    result_parts.push(format!("{}{}", prefix_group, last_unit));
                }
            }
        }
    }

    if result_parts.len() == 1 {
        result_parts.into_iter().next().unwrap()
    } else {
        result_parts.join("|")
    }
}
