        let units = split_into_units(alt);
        if units.is_empty() { continue; }
        let last = units.last().unwrap().clone();
        let prefix: String = units[..units.len()-1].join("");

        if let Some(&idx) = last_unit_to_idx.get(&last) {
            by_last_unit[idx].1.push(prefix);
