use std::collections::BTreeMap;
use crate::dfa::{Token, DFA};
use crate::cli::Config;
use crate::regex::{
    token_to_regex_str, build_char_class, is_single_regex_unit, 
    has_top_level_alternation, maybe_group
};
use crate::factor::{factor_regex, factor_by_last_unit};

/// Generate regex from a minimized DFA using forward (prefix language) approach
pub fn generate_regex(dfa: &DFA, cfg: &Config) -> String {
    let n = dfa.states.len();
    if n == 0 {
        return String::new();
    }

    // Topological sort (from initial state outward)
    let topo = topological_sort(dfa);

    // Compute Y[q] = "strings that reach state q from initial state"
    let mut prefix: Vec<String> = vec!["_UNSET_".to_string(); n];
    prefix[dfa.initial] = String::new(); // epsilon for initial state

    for &state in &topo {
        let p = prefix[state].clone();
        if p == "_UNSET_" { continue; }

        // For each transition from this state
        // Group by destination and token pattern
        let mut by_dest: BTreeMap<usize, Vec<&Token>> = BTreeMap::new();
        for (token, &dest) in &dfa.states[state].transitions {
            by_dest.entry(dest).or_default().push(token);
        }

        for (dest, tokens) in by_dest {
            // Build token pattern
            let tok_pat = build_token_pattern_sorted(&tokens, cfg);

            // Concatenate: tok_pat . p = new prefix for dest
            // But we need: strings reaching dest = {tok . str : tok in tok_pat, str in Y[state]}
            // = tok_pat . Y[state] = tok_pat . p

            let new_prefix = concat_prefix(&tok_pat, &p, cfg);

            // Combine with existing prefix for dest
            if prefix[dest] == "_UNSET_" {
                prefix[dest] = new_prefix;
            } else {
                let existing = prefix[dest].clone();
                if existing == new_prefix {
                    // No change
                } else {
                    // Combine: existing | new_prefix
                    let combined = combine_alternatives(&[existing, new_prefix], cfg);
                    prefix[dest] = combined;
                }
            }
        }
    }

    // Collect all accepting state prefixes
    let mut accepting_prefixes: Vec<String> = Vec::new();
    for (state, p) in prefix.iter().enumerate() {
        if dfa.states[state].is_accepting && p != "_UNSET_" {
            accepting_prefixes.push(p.clone());
        }
    }

    if accepting_prefixes.is_empty() {
        return String::new();
    }
    if accepting_prefixes.len() == 1 {
        return accepting_prefixes.into_iter().next().unwrap();
    }

    // Combine all accepting prefixes
    combine_alternatives(&accepting_prefixes, cfg)
}

fn topological_sort(dfa: &DFA) -> Vec<usize> {
    let n = dfa.states.len();
    let mut visited = vec![false; n];
    let mut order = Vec::new();

    fn dfs(state: usize, dfa: &DFA, visited: &mut Vec<bool>, order: &mut Vec<usize>) {
        if visited[state] { return; }
        visited[state] = true;
        for &next in dfa.states[state].transitions.values() {
            if !visited[next] {
                dfs(next, dfa, visited, order);
            }
        }
        order.push(state);
    }

    dfs(dfa.initial, dfa, &mut visited, &mut order);
    order.reverse(); // now order[0] = initial
    order
}

/// Concatenate a token pattern with an existing prefix.
/// prefix . tok_pat
fn concat_prefix(tok_pat: &str, prefix: &str, cfg: &Config) -> String {
    if prefix.is_empty() {
        return tok_pat.to_string();
    }
    if tok_pat.is_empty() {
        return prefix.to_string();
    }

    // Need to handle: if tok_pat has top-level alternation, wrap it
    if has_top_level_alternation(tok_pat) {
        let grouped = maybe_group(tok_pat, cfg.capture_groups);
        format!("{}{}", prefix, grouped)
    } else {
        format!("{}{}", prefix, tok_pat)
    }
}

/// Build token pattern from a list of tokens
fn build_token_pattern_sorted(tokens: &[&Token], cfg: &Config) -> String {
    if tokens.is_empty() {
        return String::new();
    }
    if tokens.len() == 1 {
        return token_to_regex_str(tokens[0], cfg);
    }

    let mut literal_chars: Vec<char> = Vec::new();
    let mut non_literal_pats: Vec<String> = Vec::new();

    for &tok in tokens {
        match tok {
            Token::Literal(c) => {
                if cfg.escape && *c as u32 > 127 {
                    non_literal_pats.push(crate::dfa::char_to_escape(*c, cfg.with_surrogates));
                } else {
                    literal_chars.push(*c);
                }
            }
            _ => {
                non_literal_pats.push(token_to_regex_str(tok, cfg));
            }
        }
    }

    literal_chars.sort();
    literal_chars.dedup();

    let literal_pat = if literal_chars.len() == 1 {
        Some(crate::dfa::escape_regex_char(literal_chars[0]))
    } else if literal_chars.len() > 1 {
        Some(build_char_class(&literal_chars))
    } else {
        None
    };

    let mut parts: Vec<String> = non_literal_pats;
    parts.dedup();
    if let Some(lp) = literal_pat {
        parts.push(lp);
    }

    if parts.len() == 1 {
        return parts.into_iter().next().unwrap();
    }

    // Multiple parts -> check if they have alternation
    let combined = parts.join("|");
    if has_top_level_alternation(&combined) {
        factor_regex(&combined)
    } else {
        combined
    }
}

/// Combine a list of alternative regex strings
fn combine_alternatives(alts: &[String], cfg: &Config) -> String {
    let n = alts.len();
    if n == 0 { return String::new(); }
    if n == 1 { return alts[0].clone(); }

    // Sort alternatives: longer dest (longer strings) should come first
    // Use dest-length ordering: sort by the length of what each matches
    let mut sorted: Vec<String> = alts.to_vec();
    sorted.sort_by(|a, b| {
        // Longer alternatives first
        b.len().cmp(&a.len()).then(a.cmp(b))
    });

    // Apply factoring
    factor_by_last_unit(&sorted)
}

