/// Factor alternatives by grouping those with the same FIRST unit
/// e.g., ["bc", "a", "b"] -> "bc?|a" (bc and b grouped by first char 'b')
pub fn factor_by_first_unit(alts: &[String]) -> String {
    if alts.is_empty() { return String::new(); }
    if alts.len() == 1 { return alts[0].clone(); }

    // First try quantifier merging
    if let Some(merged) = try_merge_quantifiers(alts) {
        return merged;
    }

    // Group alternatives by their first unit
    use std::collections::HashMap;
    let mut by_first: Vec<(String, Vec<String>)> = Vec::new(); // (first_unit, suffixes)
    let mut first_to_idx: HashMap<String, usize> = HashMap::new();

    for alt in alts {
        let units = split_into_units(alt);
        if units.is_empty() { 
            // Empty alternative = epsilon
            let entry = first_to_idx.entry("".to_string()).or_insert(by_first.len());
            if *entry == by_first.len() {
                by_first.push(("".to_string(), vec![alt.clone()]));
            } else {
                by_first[*entry].1.push(alt.clone());
            }
            continue;
        }
        let first = units[0].clone();
        let suffix: String = units[1..].join("");

        if let Some(&idx) = first_to_idx.get(&first) {
            by_first[idx].1.push(suffix);
        } else {
            let idx = by_first.len();
            first_to_idx.insert(first.clone(), idx);
            by_first.push((first, vec![suffix]));
        }
    }

    // Build result
    let mut result_parts: Vec<(String, String)> = Vec::new(); // (first, rest)

    for (first, suffixes) in &by_first {
        if suffixes.len() == 1 {
            // Only one alternative with this first unit
            let full = if suffixes[0].is_empty() {
                first.clone()
            } else {
                format!("{}{}", first, suffixes[0])
            };
            result_parts.push((first.clone(), full));
        } else {
            // Multiple alternatives with same first unit - factor the suffixes
            let has_empty_suffix = suffixes.iter().any(|s| s.is_empty());
            let non_empty_suffixes: Vec<String> = suffixes.iter().filter(|s| !s.is_empty()).cloned().collect();

            if non_empty_suffixes.is_empty() {
                // All alternatives are just first_unit
                result_parts.push((first.clone(), first.clone()));
            } else {
                // Factor the non-empty suffixes
                let suffix_regex = if non_empty_suffixes.len() == 1 {
                    non_empty_suffixes.into_iter().next().unwrap()
                } else {
                    factor_regex_full(&non_empty_suffixes.join("|"))
                };

                let full = if has_empty_suffix {
                    format!("{}{}", first, make_optional_str(&suffix_regex))
                } else {
                    format!("{}{}", first, make_group_if_needed(&suffix_regex))
                };
                result_parts.push((first.clone(), full));
            }
        }
    }

    if result_parts.len() == 1 {
        return result_parts.into_iter().next().unwrap().1;
    }

    // Sort result_parts: longer ones first
    result_parts.sort_by(|(_, a), (_, b)| b.len().cmp(&a.len()).then(a.cmp(b)));

    result_parts.into_iter().map(|(_, s)| s).collect::<Vec<_>>().join("|")
}
