# Fix 2: "-r" "b" "ba" "baa" "baaa" -> ^ba{1,3}?$ vs ^b(?:a{1,3})?$
# "ba{1,3}?" means b followed by a{1,3} lazily (a?). That's WRONG!
# 
# The issue: make_optional_str("a{1,3}") gives "a{1,3}?" because
# is_single_regex_unit_str("a{1,3}") returns true (it's one unit with quantifier).
# 
# But "a{1,3}?" is NOT the optional form of "a{1,3}"!
# "a{1,3}?" = match a between 1-3 times, lazily.
# "(a{1,3})?" = optionally match a{1,3} (0 or 1 times).
# 
# The fix: is_single_regex_unit_str should return false for quantified patterns,
# OR make_optional should always wrap quantified patterns in a group.
# 
# Let me check what "a{1,3}?" represents:
# It means: match 'a' 1 to 3 times, and the ? makes the quantifier LAZY (non-greedy).
# This is NOT what we want! We want "match a{1,3} ZERO or ONE times".
# 
# The correct form is "(?:a{1,3})?" or "a{0,3}" (extending the range).
# 
# In this case "a{1,3}" as optional: the answer should be "a{0,3}" or "(?:a{1,3})?".
# Grex uses "b(?:a{1,3})?" which uses the group form.
# 
# Fix: in make_optional_str, if the string ends with a quantifier (}, ?, +, *),
# always wrap it in a group rather than just appending '?'.

cat > /tmp/fix_optional.py << 'EOF'
with open('/workspace/grex_impl/src/factor.rs', 'r') as f:
    content = f.read()

old = '''fn make_optional_str(s: &str) -> String {
    if s.is_empty() { return String::new(); }
    if is_single_regex_unit_str(s) {
        format!("{}?", s)
    } else {
        format!("(?:{})?", s)
    }
}'''

new = '''fn make_optional_str(s: &str) -> String {
    if s.is_empty() { return String::new(); }
    // Check if string already ends with a quantifier
    let bytes = s.as_bytes();
    let last = bytes.last().copied().unwrap_or(0);
    let already_quantified = matches!(last, b'+' | b'*' | b'?' | b'}');

    if already_quantified {
        // Must wrap in group to avoid double-quantifier
        format!("(?:{})?", s)
    } else if is_single_regex_unit_str(s) {
        format!("{}?", s)
    } else {
        format!("(?:{})?", s)
    }
}'''

if old in content:
    content = content.replace(old, new)
    print("Fixed make_optional_str")
else:
    print("Not found")
with open('/workspace/grex_impl/src/factor.rs', 'w') as f:
    f.write(content)
EOF
