# Now add convert_to_capture_groups function to regex.rs:
cat >> /workspace/grex_impl/src/regex.rs << 'EOF'

/// Convert all non-capturing groups (?:...) to capturing groups (...)
/// This handles the -g flag
pub fn convert_to_capture_groups(s: &str) -> String {
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut result = String::with_capacity(n);
    let mut i = 0;

    while i < n {
        if bytes[i] == b'(' && i + 2 < n && bytes[i+1] == b'?' && bytes[i+2] == b':' {
            // Replace (?:  with (
            result.push('(');
            i += 3; // skip '(?:'
        } else if bytes[i] == b'(' && i + 1 < n && bytes[i+1] == b'?' && i + 2 < n && bytes[i+2] != b':' {
            // Keep special groups like (?i), (?x) as-is
            result.push('(');
            i += 1;
        } else {
            let c = s[i..].chars().next().unwrap_or('\0');
            result.push(c);
            i += c.len_utf8();
        }
    }

    result
}
EOF

